1	//! The core domain's pure laws over arbitrary inputs
2	//! (docs/testing/property.md). Email canonicalization is total and
3	//! idempotent, the UUIDv7 layout orders by its millisecond prefix, and the
4	//! id format round-trips through its parser, each over a swept space rather
5	//! than one fixed example.
6	
7	use core::str::FromStr;
8	
9	use hegel::TestCase;
10	use hegel::generators as gs;
11	
12	use sesame_core::ids::UserId;
13	use sesame_core::model::{EMAIL_MAX_LEN, EmailAddress, TimestampMillis};
14	use sesame_core::seams::rng::layout;
15	
16	const LOCAL_ALPHABET: &[u8] =
17	    b"REDACTED._%+-";
18	const DOMAIN_ALPHABET: &[u8] = b"REDACTED.-";
19	
20	fn draw_with_alphabet(tc: &TestCase, alphabet: &[u8]) -> String {
21	    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(60));
22	    let mut out = String::from('a');
23	    out.extend(
24	        bytes
25	            .iter()
26	            .map(|b| alphabet[usize::from(*b) % alphabet.len()] as char),
27	    );
28	    out
29	}
30	
