1	/**
2	 * The narinfo document: parsing, serialising, and the reference graph.
3	 *
4	 * A narinfo is a flat list of `Key: value` lines describing one store path
5	 * (`docs/contracts.md` §The narinfo format). cachet cares about it for two reasons: the `URL`
6	 * field names the NAR that must already exist before the narinfo may be stored
7	 * (Invariant NEVER-DANGLE), and the `References` field is the graph the collector walks
8	 * (ADR 0001) — there is no other copy of it anywhere.
9	 *
10	 * Unknown fields are preserved verbatim. We are a cache, not an authority on the format. A
11	 * field we do not understand must survive a store-and-serve cycle untouched, or we corrupt
12	 * artifacts for a client that does understand it — and clients verify signatures over content we
13	 * would have altered.
14	 *
15	 * The parser is total: arbitrary bytes yield a typed failure, never a throw
16	 * (Invariant CLIENT-CANNOT-CRASH).
17	 *
18	 * @module
19	 */
20	
21	import { NARINFO_BYTES_MAX, NARINFO_LINES_MAX, NARINFO_REFERENCES_MAX } from '../constants.js';
22	import { fail, ok, type Result } from '../result.js';
23	import type { NarKey, StorePathHash } from '../types.js';
24	import { parseNarKey, parseStorePath, parseStorePathBasename } from './keys.js';
25	
26	/** The fields cachet reads, plus everything it does not. */
27	export interface Narinfo {
28	    /** The full `/nix/store/<hash>-<name>` path this document describes. */
29	    readonly storePath: string;
30	    /** The NAR's bucket key. The object the write path checks for. */
31	    readonly url: NarKey;
32	    /** How the NAR is compressed. Defaults to `bzip2` when absent, as Nix does. */
33	    readonly compression: string;
34	    /** Hash of the compressed NAR. Absent for some uncompressed layouts. */
35	    readonly fileHash: string | undefined;
36	    readonly fileSizeBytes: number | undefined;
37	    /** Hash of the uncompressed NAR — what `nix store verify` checks. */
38	    readonly narHash: string;
39	    readonly narSizeBytes: number;
40	    /** `<hash>-<name>` basenames. The collector's edge list. */
41	    readonly references: readonly string[];
42	    /** May appear more than once; clients verify these against their trusted keys. */
43	    readonly signatures: readonly string[];
44	    /** Every line whose key we do not recognise, verbatim and in order. */
45	    readonly extraLines: readonly string[];
46	}
47	
48	/** why: Nix's own default when the field is absent (`docs/contracts.md`). */
49	const DEFAULT_COMPRESSION = 'bzip2';
50	
51	const SINGLE_VALUE_FIELDS = [
52	    'StorePath',
53	    'URL',
54	    'Compression',
55	    'FileHash',
56	    'FileSize',
57	    'NarHash',
58	    'NarSize',
59	    'References',
60	] as const;
61	
62	/** Fields collected during a parse, before validation. */
63	interface FieldBag {
64	    readonly single: Map<string, string>;
65	    readonly signatures: string[];
66	    readonly extraLines: string[];
67	}
68	
69	/** A non-negative integer, strictly — no signs, no whitespace, no exponents. */
70	function parseByteCount(text: string, field: string): Result<number> {
71	    if (!/^\d+$/.test(text)) {
72	        return fail('malformed_narinfo', `${field} is a non-negative integer`);
73	    }
74	    const value = Number(text);
75	    if (!Number.isSafeInteger(value)) {
76	        return fail('malformed_narinfo', `${field} is too large to represent exactly`);
77	    }
78	    return ok(value);
79	}
80	
81	/** A hash field: opaque to us, but it must at least be one non-empty token. */
82	function checkHash(text: string, field: string): Result<string> {
83	    if (text.length === 0 || /\s/.test(text)) {
84	        return fail('malformed_narinfo', `${field} is a single non-empty token`);
85	    }
86	    return ok(text);
87	}
88	
89	/** Split the document into fields, keeping unknown lines aside. */
90	function collectFields(text: string): Result<FieldBag> {
91	    const lines = text.split('\n');
92	    if (lines.length > NARINFO_LINES_MAX) {
93	        return fail(
94	            'malformed_narinfo',
95	            `a narinfo has at most ${String(NARINFO_LINES_MAX)} lines`,
96	        );
97	    }
98	
99	    const single = new Map<string, string>();
100	    const signatures: string[] = [];
101	    const extraLines: string[] = [];
102	
103	    for (const line of lines) {
104	        // A trailing newline yields one empty final element; blank lines are otherwise not
105	        // meaningful in this format, so they are dropped rather than preserved.
106	        if (line.length === 0) {
107	            continue;
108	        }
109	        const separator = line.indexOf(': ');
110	        if (separator <= 0) {
111	            return fail('malformed_narinfo', 'every narinfo line is "Key: value"');
112	        }
113	        const key = line.slice(0, separator);
114	        const value = line.slice(separator + 2);
115	
116	        if (key === 'Sig') {
117	            signatures.push(value);
118	            continue;
119	        }
120	        if (!(SINGLE_VALUE_FIELDS as readonly string[]).includes(key)) {
121	            extraLines.push(line);
122	            continue;
123	        }
124	        // why: a duplicated single-valued field is a document we cannot interpret without
125	        // guessing which one is authoritative, so it is refused rather than resolved.
126	        if (single.has(key)) {
127	            return fail('malformed_narinfo', `${key} appears more than once`);
128	        }
129	        single.set(key, value);
130	    }
131	
132	    return ok({ single, signatures, extraLines });
133	}
134	
135	/** Validate the `References` field into checked basenames. */
136	function parseReferences(raw: string | undefined): Result<readonly string[]> {
137	    if (raw === undefined || raw.length === 0) {
138	        return ok([]);
139	    }
140	    const entries = raw.split(' ').filter((entry) => entry.length > 0);
141	    if (entries.length > NARINFO_REFERENCES_MAX) {
142	        // Invariant BOUNDED-WORK: this also caps the closure walk's fan-out from one node.
143	        return fail(
144	            'malformed_narinfo',
145	            `References exceeds ${String(NARINFO_REFERENCES_MAX)} entries`,
146	        );
147	    }
148	    for (const entry of entries) {
149	        const parsed = parseStorePathBasename(entry);
150	        if (!parsed.ok) {
151	            return fail('malformed_narinfo', `References contains an invalid store path basename`);
152	        }
153	    }
154	    return ok(entries);
155	}
156	
157	/**
158	 * Parse a narinfo document.
159	 *
160	 * @example
161	 * ```ts
162	 * const parsed = parseNarinfo(await request.text());
163	 * if (!parsed.ok) return parsed;
164	 * const narKey = parsed.value.url;   // the object NEVER-DANGLE requires to exist
165	 * ```
166	 */
167	export function parseNarinfo(text: string): Result<Narinfo> {
168	    // Bound before splitting, so a huge document costs a length comparison.
169	    if (text.length > NARINFO_BYTES_MAX) {
170	        return fail('body_too_large', `a narinfo exceeds ${String(NARINFO_BYTES_MAX)} bytes`);
171	    }
172	
173	    const collected = collectFields(text);
174	    if (!collected.ok) {
175	        return collected;
176	    }
177	    const { single, signatures, extraLines } = collected.value;
178	
179	    const storePathText = single.get('StorePath');
180	    const urlText = single.get('URL');
181	    const narHashText = single.get('NarHash');
182	    const narSizeText = single.get('NarSize');
183	    if (
184	        storePathText === undefined ||
185	        urlText === undefined ||
186	        narHashText === undefined ||
187	        narSizeText === undefined
188	    ) {
189	        return fail('malformed_narinfo', 'a narinfo requires StorePath, URL, NarHash, and NarSize');
190	    }
191	
192	    const storePath = parseStorePath(storePathText);
193	    if (!storePath.ok) {
194	        return fail('malformed_narinfo', 'StorePath is not a valid store path');
195	    }
196	    const url = parseNarKey(urlText);
197	    if (!url.ok) {
198	        return fail('malformed_narinfo', 'URL is not a valid NAR key');
199	    }
200	    const narHash = checkHash(narHashText, 'NarHash');
201	    if (!narHash.ok) {
202	        return narHash;
203	    }
204	    const narSizeBytes = parseByteCount(narSizeText, 'NarSize');
205	    if (!narSizeBytes.ok) {
206	        return narSizeBytes;
207	    }
208	    const references = parseReferences(single.get('References'));
209	    if (!references.ok) {
210	        return references;
211	    }
212	
213	    const optional = parseOptionalFileFields(single);
214	    if (!optional.ok) {
215	        return optional;
216	    }
217	
218	    return ok({
219	        storePath: storePathText,
220	        url: url.value,
221	        compression: single.get('Compression') ?? DEFAULT_COMPRESSION,
222	        fileHash: optional.value.fileHash,
223	        fileSizeBytes: optional.value.fileSizeBytes,
224	        narHash: narHash.value,
225	        narSizeBytes: narSizeBytes.value,
226	        references: references.value,
227	        signatures,
228	        extraLines,
229	    });
230	}
231	
232	/** `FileHash` and `FileSize` are optional, but must be well-formed when present. */
233	function parseOptionalFileFields(
234	    single: Map<string, string>,
235	): Result<{ fileHash: string | undefined; fileSizeBytes: number | undefined }> {
236	    const fileHashText = single.get('FileHash');
237	    const fileSizeText = single.get('FileSize');
238	
239	    let fileHash: string | undefined;
240	    if (fileHashText !== undefined) {
241	        const checked = checkHash(fileHashText, 'FileHash');
242	        if (!checked.ok) {
243	            return checked;
244	        }
245	        fileHash = checked.value;
246	    }
247	
248	    let fileSizeBytes: number | undefined;
249	    if (fileSizeText !== undefined) {
250	        const parsed = parseByteCount(fileSizeText, 'FileSize');
251	        if (!parsed.ok) {
252	            return parsed;
253	        }
254	        fileSizeBytes = parsed.value;
255	    }
