/**
 * Key and path validation — the boundary between a URL and a bucket key.
 *
 * Nothing reaches the bucket that has not come through this module. That makes it the
 * path-traversal guard as much as a format check (Invariant BOUNDED-WORK): the patterns are
 * derived from the Nix base-32 alphabet and the layouts in `docs/contracts.md`, and anything
 * outside them is refused. There is no escaping, normalising, or sanitising step, because a
 * validator that transforms its input is a validator you have to reason about twice.
 *
 * Every function here is total: arbitrary bytes yield a typed failure, never a throw
 * (Invariant CLIENT-CANNOT-CRASH).
 *
 * @module
 */

import {
    KEY_BYTES_MAX,
    NAR_FILE_HASH_LENGTH,
    NAR_KEY_PREFIX,
    NAR_SUFFIX_BY_COMPRESSION,
    NARINFO_KEY_SUFFIX,
    NIX_BASE32_ALPHABET,
    NIX_STORE_DIR,
    RESERVED_KEY_PREFIXES,
    STORE_PATH_HASH_LENGTH,
    STORE_PATH_NAME_BYTES_MAX,
} from '../constants.js';
import { fail, ok, type Result } from '../result.js';
import { parseStorePathHash, type NarKey, type StorePathHash } from '../types.js';

/** Escape a literal for inclusion in a regular expression. */
function escapeForPattern(literal: string): string {
    return literal.replaceAll(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/**
 * why: the accepted NAR key shape, assembled from the contract rather than hand-written, so the
 * suffix list and the hash length cannot drift from `NAR_SUFFIX_BY_COMPRESSION` and
 * `NAR_FILE_HASH_LENGTH`. Anchored at both ends: an unanchored pattern would accept
 * `../../nar/<hash>.nar` because it matches somewhere inside.
 */
const NAR_KEY_PATTERN = (() => {
    const suffixes = Object.values(NAR_SUFFIX_BY_COMPRESSION)
        .filter((suffix) => suffix.length > 0)
        .map(escapeForPattern);
    const alphabet = `[${NIX_BASE32_ALPHABET}]`;
    return new RegExp(
        `^${escapeForPattern(NAR_KEY_PREFIX)}${alphabet}{${String(NAR_FILE_HASH_LENGTH)}}\\.nar(?:${suffixes.join('|')})?$`,
    );
})();

/**
 * why: the name half of a store path. Nix permits letters, digits, and `+-._?=`; notably it does
 * not permit `/`, which is what stops a name from smuggling a path segment.
 */
const STORE_PATH_NAME_PATTERN = /^[a-zA-Z0-9+._?=-]+$/;

/** A store path, split into the parts we care about. */
export interface StorePathParts {
    readonly hash: StorePathHash;
    readonly name: string;
}

/**
 * Validate a narinfo request path.
 *
 * @param requestPath - the URL path, with or without its leading slash
 *
 * @example
 * ```ts
 * const parsed = parseNarinfoRequestPath('/REDACTED.narinfo');
 * ```
 */
export function parseNarinfoRequestPath(requestPath: string): Result<StorePathHash> {
    const bounded = boundedPath(requestPath);
    if (!bounded.ok) {
        return bounded;
    }
    if (!bounded.value.endsWith(NARINFO_KEY_SUFFIX)) {
        return fail('malformed_key', 'a narinfo path ends in .narinfo');
    }
    return parseStorePathHash(bounded.value.slice(0, -NARINFO_KEY_SUFFIX.length));
}

/**
 * Validate a NAR request path.
 *
 * The returned key is the bucket key verbatim — `nar/<hash>.nar<suffix>` — because the cache's
 * URL space and the bucket's key space are the same for NARs.
 */
export function parseNarRequestPath(requestPath: string): Result<NarKey> {
    const bounded = boundedPath(requestPath);
    if (!bounded.ok) {
        return bounded;
    }
    return parseNarKey(bounded.value);
}

/**
 * Validate a NAR key as it appears in a narinfo's `URL` field.
 *
 * Same shape as a request path, different provenance: this one arrives inside a document a client
 * uploaded, and it decides which object the write path will `head` to enforce NEVER-DANGLE. A
 * loose check here would let a narinfo point at an object outside the NAR key space.
 */
export function parseNarKey(text: string): Result<NarKey> {
    if (text.length > KEY_BYTES_MAX) {
        return fail('malformed_key', `a key exceeds ${String(KEY_BYTES_MAX)} bytes`);
    }
    if (!NAR_KEY_PATTERN.test(text)) {
        return fail(
            'malformed_key',
            'a NAR key is nar/<52 base-32 characters>.nar with an optional compression suffix',
        );
    }
    return ok(text as NarKey);
}

/**
 * Validate a full store path and split it.
 *
 * Used for the `StorePath` field of a narinfo and for every entry in a roots payload.
 */
export function parseStorePath(text: string): Result<StorePathParts> {
    const prefix = `${NIX_STORE_DIR}/`;
    if (text.length > prefix.length + STORE_PATH_HASH_LENGTH + 1 + STORE_PATH_NAME_BYTES_MAX) {
        return fail('malformed_key', 'a store path is longer than any Nix store path can be');
    }
    if (!text.startsWith(prefix)) {
        return fail('malformed_key', `a store path begins with ${prefix}`);
    }

    const basename = text.slice(prefix.length);
    // why: paired enforcement (CLAUDE.md §5), and redundant. A traversal like
    // `/nix/store/<hash>-<name>/../etc` is refused here and by the name charset below, which
    // does not admit `/`. Either check alone suffices today; both exist so that widening the
    // name charset later — the plausible future change — cannot silently open a traversal. The
    // tests verify the redundancy is real by disabling each guard in turn.
    if (basename.includes('/')) {
        return fail(
            'malformed_key',
            'a store path has no path separator after the store directory',
        );
    }
    return parseStorePathBasename(basename);
}

/**
 * Validate a `<hash>-<name>` basename — the form the `References` field uses.
 *
 * References name paths without the store directory, so this is the reference-graph entry point
 * and therefore what the closure walk depends on.
 */
export function parseStorePathBasename(basename: string): Result<StorePathParts> {
    if (basename.length < STORE_PATH_HASH_LENGTH + 2) {
        return fail('malformed_key', 'a store path basename is <hash>-<name>');
    }
    const separator = basename[STORE_PATH_HASH_LENGTH];
    if (separator !== '-') {
        return fail('malformed_key', 'a store path basename separates hash and name with a dash');
    }

    const hash = parseStorePathHash(basename.slice(0, STORE_PATH_HASH_LENGTH));
    if (!hash.ok) {
        return hash;
    }

    const name = basename.slice(STORE_PATH_HASH_LENGTH + 1);
    if (name.length > STORE_PATH_NAME_BYTES_MAX) {
        return fail(
            'malformed_key',
            `a store path name exceeds ${String(STORE_PATH_NAME_BYTES_MAX)} bytes`,
        );
    }
    if (!STORE_PATH_NAME_PATTERN.test(name)) {
        return fail('malformed_key', 'a store path name uses only letters, digits, and +-._?=');
    }
    return ok({ hash: hash.value, name });
}

/**
 * Whether a key belongs to one of the internal prefixes.
 *
 * Paired enforcement (CLAUDE.md §5): validation already makes these unreachable from a request,
 * and this is the second, independent check used on the deletion side, where being wrong is
 * unrecoverable (`docs/contracts.md` §The key space).
 */
export function isReservedKey(key: string): boolean {
    return RESERVED_KEY_PREFIXES.some((prefix) => key.startsWith(prefix));
}

/** Bound a request path and strip its leading slash. */
function boundedPath(requestPath: string): Result<string> {
    // A cheap upper bound before touching the string, so a pathological path costs one comparison.
    // The `+ 1` is the leading slash a routed path carries.
    if (requestPath.length > KEY_BYTES_MAX + 1) {
        return fail('malformed_key', `a request path exceeds ${String(KEY_BYTES_MAX)} bytes`);
    }

    const trimmed = requestPath.startsWith('/') ? requestPath.slice(1) : requestPath;
    if (trimmed.length === 0) {
        return fail('malformed_key', 'an empty request path');
    }

    // why: bounded again, on the trimmed value, as a typed failure rather than an assertion. The
    // slash allowance above means a path arriving without one can be `KEY_BYTES_MAX + 1` long and
    // still pass it — and this function used to assert here instead, and that assertion let a
    // client-supplied string raise a 500 and an alert where the contract requires a 400. An
    // assertion is for cachet being wrong about itself, never for anything a caller can send
    // (Invariant CLIENT-CANNOT-CRASH). Nothing forces a caller to include the slash: hono always
    // does, but that is an accident of the router rather than a guard, and this function is
    // documented as accepting a path with or without one.
    if (trimmed.length > KEY_BYTES_MAX) {
        return fail('malformed_key', `a request path exceeds ${String(KEY_BYTES_MAX)} bytes`);
    }
    return ok(trimmed);
}

