/**
 * The client-facing failure vocabulary: a `Result` for parse and validation outcomes, and
 * a {@link ClientError} carrying the HTTP status the edge will return.
 *
 * Every condition a client can cause lands here rather than in an assertion
 * (CLAUDE.md §4, Invariant CLIENT-CANNOT-CRASH). The status for a given code is fixed by
 * the table below and nowhere else, so a code can never mean 400 on one route and 409 on
 * another.
 *
 * @module
 */

/**
 * Every client-reachable failure, with the status it maps to.
 *
 * why: one table, so the mapping from a code to its status is a single reviewable fact. Adding a case
 * here is how a new failure mode enters the system; the type of {@link ClientErrorCode} is
 * derived from these keys, so a handler cannot invent an unmapped code.
 */
const STATUS_BY_CODE = {
    /** Key length or format rejected — also the path-traversal guard (docs/contracts.md). */
    malformed_key: 400,
    /** The narinfo did not parse, or a required field was missing or malformed. */
    malformed_narinfo: 400,
    /** The roots payload did not parse, or an entry was not a valid store path. */
    malformed_roots: 400,
    /** The `Authorization` header was unparseable or oversized. */
    malformed_auth: 400,
    /** A multipart part number outside `1..expectedParts`. */
    part_number_invalid: 400,
    /** A part whose length violates R2's uniform-part-size rule (docs/contracts.md §R2). */
    part_size_mismatch: 400,
    /** The completion part set was not exactly the expected parts, or contained duplicates. */
    complete_parts_mismatch: 400,
    /** No credential, or one that did not verify. */
    unauthorized: 401,
    /** A valid OIDC token from outside the configured org. */
    forbidden_org: 403,
    /** Lease renewal attempted from a ref other than the configured default branch. */
    forbidden_ref: 403,
    /** No such object. Nix reads the 404 as a cache miss and moves to the next substituter rather than retrying, so a build never fails on it (Invariant FAIL-TOWARD-REBUILD). */
    not_found: 404,
    /** The upload id has no bookkeeping record: unknown, already completed, or aborted. */
    upload_unknown: 404,
    /**
     * A narinfo whose NAR is absent. The write-time half of Invariant NEVER-DANGLE: the
     * uploader's NAR-before-narinfo ordering is verified here rather than trusted.
     */
    narinfo_nar_missing: 409,
    /** A write without `Content-Length`: the size guard cannot run, so the write cannot. */
    length_required: 411,
    /** Body or payload over its cap (Invariant BOUNDED-WORK). */
    body_too_large: 413,
    /**
     * The JWKS could not be fetched and no fresh cached copy exists, so an OIDC token can
     * be neither accepted nor honestly rejected. The 503 is never a bypass, because it tells the
     * client to retry, and Nix falls through to the next substituter meanwhile.
     */
    auth_unavailable: 503,
    /**
     * A bucket operation the request depended on failed.
     *
     * why: distinct from every 4xx above, because the client did nothing wrong and retrying is the
     * correct response. It is also distinct from an invariant violation: a store rejecting a write is
     * an expected error to handle rather than evidence that cachet is broken.
     */
    storage_unavailable: 503,
} as const satisfies Record<string, number>;

/** Every client-reachable failure code. Derived from {@link STATUS_BY_CODE}. */
export type ClientErrorCode = keyof typeof STATUS_BY_CODE;

/**
 * A failure the client caused, or at least can see and act on.
 *
 * Carries a stable machine-readable `code` alongside the status, so clients and our own
 * tests can distinguish "your key was malformed" from "your narinfo was" without parsing
 * prose.
 */
export class ClientError extends Error {
===ROOTS PAYLOAD===
 * if (!payload.ok) return payload;
 * ```
 */
export function parseRootsPayload(text: string): Result<RootsPayload> {
    // Bound on bytes before parsing, so an enormous body costs a length comparison.
    if (text.length > ROOTS_BODY_BYTES_MAX) {
        return fail(
            'body_too_large',
            `a roots payload exceeds ${String(ROOTS_BODY_BYTES_MAX)} bytes`,
        );
    }

    let parsed: unknown;
    try {
        parsed = JSON.parse(text);
    } catch {
        return fail('malformed_roots', 'a roots payload is a JSON object');
    }
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        return fail('malformed_roots', 'a roots payload is a JSON object');
    }

    const raw = parsed as { storePaths?: unknown; installables?: unknown };
    const storePaths = parseStringList(raw.storePaths, 'storePaths', ROOTS_PATHS_MAX);
    if (!storePaths.ok) {
        return storePaths;
    }
    // Independently of the array cap: an installable list is metadata, and a huge one is a mistake.
    const installables = parseStringList(raw.installables, 'installables', ROOTS_PATHS_MAX);
    if (!installables.ok) {
        return installables;
    }

    // why: an installable is passed to `nix build` as an argv entry, so one beginning with a dash could
    // be read as a command-line flag rather than a flake reference. The verifier now separates
    // installables from flags with `--`, and a dash-prefixed entry is refused here as well — paired
    // enforcement (CLAUDE.md §5), on the side where the value enters the system rather than only where
    // it is used. An `--option substitute true` reaching that argv would switch substitution back on and
    // make the verifier compare the cache against itself, so the actor who could poison the cache is the
    // one who could blind the check on it, and both come from the same write credential.
    for (const installable of installables.value) {
        if (installable.startsWith('-')) {
            return fail(
                'malformed_roots',
                'installables contains an entry beginning with "-", which would read as a command-line flag',
            );
        }
    }

    for (const path of storePaths.value) {
        const checked = parseStorePath(path);
        if (!checked.ok) {
            return fail(
                'malformed_roots',
                'storePaths contains an entry that is not a valid store path',
            );
        }
    }

    return ok({ storePaths: storePaths.value, installables: installables.value });
}

