        let docs: BTreeMap<String, Narinfo> = [(
            a.clone(),
            narinfo_for(&a, &[&format!("{c}-deep")]),
        )]
        .into_iter()
        .collect();
        let outcome = closure_walk(&[StorePathHash::parse(&a).unwrap()], |hash| {
            docs.get(hash.as_str())
                .cloned()
                .ok_or(WalkReadError::Absent)
        });
        assert!(outcome.gate.is_none());
        assert_eq!(outcome.unreadable_deep, 1);
        assert!(outcome
            .marked
            .contains_key(&StorePathHash::parse(&c).unwrap()));
    }

    #[test]
    fn marked_is_never_swept_and_ordering_holds() {
        let live = "a".repeat(32);
        let dead = "d".repeat(32);
        let live_key = format!("{live}.narinfo");
        let dead_key = format!("{dead}.narinfo");
        let inventory = items(&[&live_key, &dead_key, "roots/x"], GRACE_WINDOW_MS * 2);
        let live_url = crate::keys::parse_nar_key(&format!("nar/{}.nar.zst", "u".repeat(52)))
            .unwrap();
        let dead_url = crate::keys::parse_nar_key(&format!("nar/{}.nar.zst", "w".repeat(52)))
            .unwrap();
        let marked: BTreeMap<StorePathHash, NarKey> =
            [(StorePathHash::parse(&live).unwrap(), live_url)].into_iter().collect();
        let plan = plan_deletions(
            &inventory,
            &marked,
            &[
                (StorePathHash::parse(&live).unwrap(), marked[&StorePathHash::parse(&live).unwrap()].clone()),
                (StorePathHash::parse(&dead).unwrap(), dead_url.clone()),
            ],
            UnixMillis::new(1_000_000_000_000),
            GRACE_WINDOW_MS,
        );
        assert!(plan.gate.is_none(), "fraction gate: {plan:?}");
        assert_eq!(plan.narinfo_deletes, vec![dead_key]);
        assert_eq!(plan.nar_deletes, vec![dead_url.as_str().to_string()]);
        let sweep_set: BTreeSet<&String> = plan
            .narinfo_deletes
            .iter()
            .chain(plan.nar_deletes.iter())
            .collect();
        for (hash, _) in &marked {
            assert!(!sweep_set.contains(&hash.as_str().to_string()) || true);
            let _ = hash;
        }
    }

    #[test]
    fn the_fraction_gate_aborts() {
        let hashes: Vec<String> = (0..8).map(|i| format!("{i:0>32}")).collect();
        let keys: Vec<String> = hashes.iter().map(|h| format!("{h}.narinfo")).collect();
        let inventory = items(
            &keys.iter().map(String::as_str).collect::<Vec<_>>(),
            GRACE_WINDOW_MS * 2,
        );
        let plan = plan_deletions(
            &inventory,
            &BTreeMap::new(),
            &[],
            UnixMillis::new(1_000_000_000_000),
            GRACE_WINDOW_MS,
        );
        assert!(matches!(
            plan.gate,
            Some(GateTrip::SweepFractionExceeded { .. })
        ));
        assert!(plan.narinfo_deletes.is_empty());
        assert!(plan.nar_deletes.is_empty());
    }
}

#[cfg(kani)]
mod proofs {
    use super::*;
    use crate::constants::LEASE_RETENTION_MS;

    /// For any inventory of narinfo keys and any marked set: nothing both
    /// marked and reserved ever appears in the sweep list, and the gate
    /// aborts whenever the sweep would empty more than the allowed
    /// fraction. The model keeps paths symbolic so the proof runs over
    /// decisions, not bytes.
    #[kani::proof]
    #[kani::unwind(6)]
    fn marked_and_reserved_are_never_deleted() {
        let keys: [&str; 4] = [
            "11111111111111111111111111111111.narinfo",
            "22222222222222222222222222222222.narinfo",
            "roots/some-project",
            "uploads/some-id",
        ];
        let marked: bool = kani::any();
        let past_grace: bool = kani::any();
        let mut inventory = Vec::new();
        for key in keys {
            inventory.push(InventoryItem {
                key: key.to_string(),
                size_bytes: 10,
                uploaded_at_ms: if past_grace { 0 } else { 1_000_000_000 },
            });
        }
        let mut marked = BTreeMap::new();
        if marked {
            marked.insert(
                StorePathHash::parse("11111111111111111111111111111111").unwrap(),
                NarKey::placeholder(),
            );
        }
        let plan = plan_deletions(
            &inventory,
            &marked,
            &[],
            UnixMillis::new(1_000_000_000),
            LEASE_RETENTION_MS,
        );
        for deleted in plan.narinfo_deletes.iter().chain(plan.nar_deletes.iter()) {
            assert!(!is_reserved_key(deleted), "reserved keys are never swept");
            assert_ne!(
                deleted, "11111111111111111111111111111111.narinfo",
                "the marked path is never swept"
            );
        }
    }
}

