fn narinfo_parse_is_total(tc: TestCase) {
    let bytes: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(2_000));
    let text = String::from_utf8_lossy(&bytes);
    let _ = Narinfo::parse(&text);
