}

#[cfg(kani)]
mod proofs {
    use super::*;

    /// Sign-round-tripped bytes always verify; any one-bit tamper in the
    /// fingerprint, the key, or the signature fails verification.
    #[kani::proof]
    fn sign_verify_round_trip_and_tamper() {
        let seed: [u8; 32] = kani::any();
        let fp_len: usize = kani::any();
        kani::assume(fp_len <= 24);
        let mut fingerprint = vec![0u8; fp_len];
        for b in fingerprint.iter_mut() {
            *b = kani::any();
        }
        let fingerprint = String::from_utf8_lossy(&fingerprint).into_owned();
        let key = NixSecretKey::from_seed("k", &seed).expect("seeds derive");
        let sig = key.sign_fingerprint(&fingerprint);
