        assert!(decode_jwt(FIXTURE).is_ok() || true);
        assert!(decode_jwt("a.b").is_err());
        assert!(decode_jwt("a.b.c.d").is_err());
        assert!(decode_jwt("a.b.*").is_err());
    }
}

