131	    /// [`ZstdStream::finish`]) on a stream that ends mid-frame.
132	    pub fn push(&mut self, bytes: &[u8]) -> Result<Vec<u8>, ZstdError> {
133	        self.pipe.append(bytes);
134	        let mut produced = Vec::new();
