78	/// Why a narinfo read failed during the walk.
79	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
80	pub enum WalkReadError {
81	    /// The narinfo object is absent (a dangling root or reference).
82	    Absent,
83	    /// The object exists but does not parse.
84	    Unparseable,
85	}
86	
87	/// The pure outcome of the closure walk over one root set.
88	#[derive(Debug, Clone, Default)]
89	pub struct WalkOutcome {
90	    /// Every reachable store-path hash.
91	    pub marked: BTreeSet<StorePathHash>,
92	    /// For each readable marked path, the NAR key its narinfo named. The
93	    /// URL set derived from this map is what makes shared-NAR sweeps safe:
94	    /// a NAR survives if any marked narinfo still names it.
95	    pub marked_urls: BTreeMap<StorePathHash, NarKey>,
96	    /// Deep references whose own narinfo could not be read: they are
97	    /// marked without descent and counted for the report.
98	    pub unreadable_deep: usize,
99	    /// The gate a run aborts on, when one tripped.
100	    pub gate: Option<GateTrip>,
101	}
102	
103	/// Walk the reference graph from the root hashes, breadth-first, one
104	/// narinfo read per newly visited path. Root read failures trip the
105	/// walk-aborting gate; deep failures mark the node without descending,
106	/// because the alternative, deleting under it, would eat descendants we
107	/// cannot see. The walk is deterministic: insertion-ordered queue over
108	/// sorted roots, `BTreeSet` visited set.
109	pub fn closure_walk(
110	    roots: &[StorePathHash],
111	    mut read_narinfo: impl FnMut(&StorePathHash) -> std::result::Result<Narinfo, WalkReadError>,
112	) -> WalkOutcome {
113	    let mut outcome = WalkOutcome::default();
114	    let mut visited = BTreeSet::new();
115	    let mut queue: VecDeque<StorePathHash> = roots.iter().cloned().collect();
116	    queue.make_contiguous().sort();
117	
118	    while let Some(hash) = queue.pop_front() {
119	        if !visited.insert(hash.clone()) {
120	            continue;
121	        }
122	        if visited.len() > CLOSURE_WALK_PATHS_MAX {
123	            outcome.gate = Some(GateTrip::WalkBudgetExhausted {
124	                visited: visited.len(),
125	            });
126	            return outcome;
127	        }
128	        match read_narinfo(&hash) {
129	            Ok(document) => {
130	                let url = document.url.clone();
131	                for edge in document.reference_hashes() {
132	                    if !visited.contains(&edge) {
133	                        queue.push_back(edge);
134	                    }
135	                }
136	                outcome.marked.insert(hash.clone());
137	                outcome.marked_urls.insert(hash, url);
138	            }
139	            Err(_) => {
140	                let is_root = roots.contains(&hash);
141	                outcome.marked.insert(hash.clone());
142	                if is_root {
143	                    outcome.gate = Some(GateTrip::UnreadableRootNarinfo { hash });
144	                    return outcome;
145	                }
146	                outcome.unreadable_deep += 1;
147	            }
148	        }
149	    }
150	    outcome
151	}
