pub fn encode(data: &[u8]) -> String {
    let out_len = encoded_len(data.len());
    let mut out = String::with_capacity(out_len);
    for n in (0..out_len).rev() {
        let bit = n * 5;
        let (i, j) = (bit / 8, bit % 8);
        let mut group = u16::from(data[i] >> j);
        if i + 1 < data.len() && j > 0 {
            group |= u16::from(data[i + 1]) << (8 - j);
        }
        out.push(char::from(DIGITS[(group & 0x1f) as usize]));
    }
    out
}

/// Why a decode failed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DecodeError {
    /// The input carried a character outside the nix alphabet.
    InvalidDigit(char),
}

impl core::fmt::Display for DecodeError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Self::InvalidDigit(c) => write!(f, "invalid nix base32 digit {c:?}"),
        }
    }
}

impl std::error::Error for DecodeError {}

/// Decode a nix base32 string back to bytes. Output size follows the data:
/// `floor(len * 5 / 8)` bytes plus spill bits when the packing needs them.
///
/// # Errors
///
/// [`DecodeError::InvalidDigit`] on any character outside the alphabet.
pub fn decode(text: &str) -> Result<Vec<u8>, DecodeError> {
    let mut out: Vec<u8> = Vec::with_capacity(text.len() * 5 / 8);
    for (pos, n) in (0..text.len()).rev().enumerate() {
        let bit = n * 5;
        let (i, j) = (bit / 8, bit % 8);
        // why: the digit is an index into a 32-entry alphabet, so the
        // narrowing conversions below cannot truncate anything real; the
        // try_from keeps the claim explicit.
        let digit = u8::try_from(
            DIGITS
                .iter()
                .position(|&d| d == text.as_bytes()[pos])
                .ok_or(DecodeError::InvalidDigit(text.as_bytes()[pos] as char))?,
        )
        .expect("an index into a 32-entry alphabet");
        while out.len() <= i {
            out.push(0);
        }
        out[i] |= ((u32::from(digit) << j) & 0xff) as u8;
        let shift = u8::try_from(8 - j).expect("j < 8");
        let spill = digit >> shift;
        if spill > 0 {
            while out.len() <= i + 1 {
                out.push(0);
            }
            out[i + 1] |= spill;
        }
    }
    Ok(out)
}

/// `sha256:<nix32>` of the given bytes: the way hashes appear inside a
/// narinfo.
pub fn sha256_nix32_text(bytes: &[u8]) -> String {
    format!("sha256:{}", encode(&crate::sha256::sha256(bytes)))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn encode_matches_file_hash_vector() {
        let data = hex::decode("de04bbe5f74e4d1758b2e82e31b8bb467786b9a99659707145ecb661ed109d86")
            .expect("hex");
        assert_eq!(
            encode(&data),
            "11lx23nn3dpc8mqp0ncnm6wqcxs6pfw32bp8n9c1fkafyzjvn16y"
        );
    }

    #[test]
    fn store_hash_round_trip() {
        let hash = "qvqa04f0m85m0a6xxnan5vxnwg2jkgl9";
        assert_eq!(encode(&decode(hash).expect("decodes")), hash);
    }

    #[test]
    fn decode_refuses_foreign_digits() {
        assert!(decode("abc efg").is_err());
        assert!(decode("abco").is_err()); // 'o' is not in the alphabet
    }
}

#[cfg(kani)]
mod proofs {
    use super::*;

    /// The 20-byte store-hash width: decode of encode is the identity, and
    /// the encoding stays 32 chars of alphabet.
    #[kani::proof]
    #[kani::unwind(35)]
    fn base32_20_round_trip() {
        let data: [u8; 20] = kani::any();
        let encoded = encode(&data);
        for c in encoded.bytes() {
            assert!(DIGITS.contains(&c));
        }
        let decoded = decode(&encoded).expect("own encoding decodes");
        assert!(decoded[..] == data[..]);
    }
}

# One toolchain resolution, one dependency closure: every check shares
# compiled dependencies through _module.args, and no module re-derives them.
# cachet-worker builds for wasm32 only, so the host closures exclude it; the
# wasm build is a dedicated verb (justfile) rather than a host check.
{ inputs, lib, ... }:
{
  perSystem =
    { system, ... }:
    let
      pkgs = import inputs.nixpkgs {
        inherit system;
        overlays = [ (import inputs.rust-overlay) ];
      };
      toolchain = pkgs.rust-bin.fromRustupToolchainFile ../rust-toolchain.toml;
      craneLib = (inputs.crane.mkLib pkgs).overrideToolchain toolchain;
      src = lib.cleanSourceWith {
        src = ../.;
        filter =
          path: type:
          let
            rel = lib.removePrefix (toString ../. + "/") (toString path);
          in
          (craneLib.filterCargoSources path type)
          # why: clippy reads the disallowed lists at lint time.
          || (rel == "clippy.toml")
          # why: nextest reads the ci profile at run time.
          || (rel == ".config/nextest.toml")
          # why: the committed OpenAPI document is served byte-for-byte and
          # compared by the golden lane.
          || (rel == "docs/openapi.yaml")
          # why: golden vectors against real nix outputs live outside cargo's
          # file list.
          || (lib.hasInfix "/fixtures/" rel)
          # why: insta snapshots are the golden lane's expected bytes;
          # cargo's source filter does not know them.
          || (lib.hasSuffix ".snap" rel);
      };
      commonArgs = {
        inherit src;
        pname = "cachet";
        version = "0.0.1";
        strictDeps = true;
      };
      # why: deny.toml stays out of the crane source on purpose: the deny
      # gate fetches the advisory database and is impure by design, so it
      # runs in the dev shell, never as a flake check.
      cargoArtifacts = craneLib.buildDepsOnly (
        commonArgs
        // {
          # why: cachet-worker is wasm32-only; the host closure covers the
          # five crates that build natively.
          cargoExtraArgs = "--workspace --exclude cachet-worker --all-features --locked";
        }
      );
    in
    {
      _module.args = {
        inherit
          pkgs
          toolchain
          craneLib
          src
          commonArgs
          cargoArtifacts
          ;
      };
    };
}

