#[cfg(kani)]
mod proofs {
    use super::*;

    /// Over any inventory of five keys (four narinfos plus a reserved
    /// bookkeeping key) with symbolic ages and a symbolic marked set:
    /// reserved keys are never swept, marked hashes are never swept, and a
    /// tripped gate always means an empty plan. The keys are concrete
    /// literals; ages and marks are the only symbolic inputs, so the proof
    /// runs over planning decisions, not over char-level string reasoning.
    ///
    /// Non-vacuity: KEY_D is always old and never marked, so it is a
    /// candidate on every path; whenever the fraction gate stays untripped
    /// the plan is nonempty and the marked/reserved assertions see real
    /// deletions. The unwind bound covers the 32-byte hash-validation
    /// loops and the alphabet scans nested inside them.
    #[kani::proof]
    #[kani::unwind(40)]
    #[kani::solver(kissat)]
    fn marked_and_reserved_are_never_deleted() {
        const KEY_A: &str = "11111111111111111111111111111111.narinfo";
        const KEY_B: &str = "22222222222222222222222222222222.narinfo";
        const KEY_C: &str = "33333333333333333333333333333333.narinfo";
        const KEY_D: &str = "44444444444444444444444444444444.narinfo";
        const HASH_A: &str = "11111111111111111111111111111111";
        const HASH_B: &str = "22222222222222222222222222222222";
        let mark_a: bool = kani::any();
        let mark_b: bool = kani::any();
        // Fresh or old against the grace window: nothing else about an age
        // changes the plan, so each item's age is one symbolic bit.
        let age = |old: bool| {
            if old { 0 } else { 10_000_000_000 }
        };
        let inventory = vec![
            InventoryItem {
                key: KEY_A.to_string(),
                size_bytes: 10,
                uploaded_at_ms: age(kani::any()),
            },
            InventoryItem {
                key: KEY_B.to_string(),
                size_bytes: 10,
                uploaded_at_ms: age(kani::any()),
            },
            InventoryItem {
                key: KEY_C.to_string(),
                size_bytes: 10,
                uploaded_at_ms: age(kani::any()),
            },
            InventoryItem {
                key: KEY_D.to_string(),
                size_bytes: 10,
                uploaded_at_ms: 0,
            },
            InventoryItem {
                key: "roots/some-project".to_string(),
                size_bytes: 10,
                uploaded_at_ms: 10_000_000_000,
            },
        ];
        let mut marked = BTreeSet::new();
        if mark_a {
            marked.insert(StorePathHash::parse(HASH_A).unwrap());
        }
        if mark_b {
            marked.insert(StorePathHash::parse(HASH_B).unwrap());
        }
        let plan = plan_deletions(
            &inventory,
            &marked,
            &BTreeMap::new(),
            &[],
            UnixMillis::new(10_000_000_000),
            1_000,
        );
        if plan.gate.is_some() {
            assert!(plan.narinfo_deletes.is_empty() && plan.nar_deletes.is_empty());
        } else {
            // The always-old, never-marked path must be in the sweep.
            assert!(plan.narinfo_deletes.iter().any(|key| key == KEY_D));
        }
        for deleted in &plan.narinfo_deletes {
            assert!(!is_reserved_key(deleted), "reserved keys are never swept");
            if mark_a {
                assert!(deleted.as_str() != KEY_A, "a marked path is never swept");
            }
            if mark_b {
                assert!(deleted.as_str() != KEY_B, "a marked path is never swept");
            }
        }
    }
}

