1	//! The core's pure laws over arbitrary inputs (docs/testing/property.md).
2	//! Law classes: totality (a function answers Ok or a typed refusal over any
3	//! input), round-trips, and plan laws for uploads and GC.
4	
5	use cachet_core::constants::{MULTIPART_PARTS_MAX, UPLOAD_PART_BYTES};
6	use cachet_core::error::ClientError;
7	use cachet_core::keys::{
8	    parse_nar_request_path, parse_narinfo_request_path, parse_store_path, parse_store_path_basename,
9	};
10	use cachet_core::multipart::{part_plan, plan_shape};
11	use cachet_core::narinfo::Narinfo;
12	use hegel::TestCase;
13	use hegel::generators as gs;
14	
15	#[hegel::test(test_cases = 256)]
16	fn plan_shape_sums_and_bounds(tc: TestCase) {
17	    let total = tc.draw(gs::integers::<u64>());
18	    match plan_shape(total) {
19	        Ok(shape) => {
20	            assert!(total > 0 && total <= UPLOAD_PART_BYTES * MULTIPART_PARTS_MAX);
21	            assert_eq!(
22	                (shape.count - 1) * UPLOAD_PART_BYTES + shape.last_len,
23	                total
24	            );
25	            assert!(shape.count >= 1 && shape.count <= MULTIPART_PARTS_MAX);
26	            assert!(shape.last_len >= 1 && shape.last_len <= UPLOAD_PART_BYTES);
27	        }
28	        Err(code) => {
29	            assert!(total == 0 || total > UPLOAD_PART_BYTES * MULTIPART_PARTS_MAX);
30	            assert!(matches!(
31	                code,
32	                ClientError::LengthRequired | ClientError::BodyTooLarge
33	            ));
34	        }
35	    }
36	}
37	
38	#[hegel::test(test_cases = 256)]
39	fn part_plan_sums_and_bounds(tc: TestCase) {
40	    let total = tc.draw(gs::integers::<u64>());
41	    match part_plan(total) {
42	        Ok(plan) => {
43	            assert!(total > 0 && total <= UPLOAD_PART_BYTES * MULTIPART_PARTS_MAX);
44	            assert_eq!(plan.parts.iter().map(|p| p.len).sum::<u64>(), total);
45	            assert!(u64::try_from(plan.parts.len()).expect("len fits") <= MULTIPART_PARTS_MAX);
46	            assert_eq!(plan.parts[0].number, 1);
47	            let last = plan.parts.len() - 1;
48	            for (i, part) in plan.parts.iter().enumerate() {
49	                assert!(part.len > 0);
50	                assert_eq!(part.number, u64::try_from(i).expect("fits") + 1);
51	                if i != last {
52	                    assert_eq!(part.len, UPLOAD_PART_BYTES);
53	                }
54	            }
55	        }
56	        Err(code) => {
57	            assert!(total == 0 || total > UPLOAD_PART_BYTES * MULTIPART_PARTS_MAX);
58	            assert!(matches!(
59	                code,
60	                ClientError::LengthRequired | ClientError::BodyTooLarge
61	            ));
62	        }
63	    }
64	}
65	
66	// why: the grammars are the path-traversal guard; a panic anywhere in them
67	// is a client-induced 500. Arbitrary bytes, arbitrary lengths.
68	#[hegel::test(test_cases = 512)]
69	fn key_parsers_are_total(tc: TestCase) {
70	    let bytes: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(300));
71	    let text = String::from_utf8_lossy(&bytes);
72	    let _ = parse_narinfo_request_path(&text);
73	    let _ = parse_nar_request_path(&text);
74	    let _ = parse_store_path(&text);
75	    let _ = parse_store_path_basename(&text);
76	}
77	
78	// why: the narinfo parser faces untrusted bytes on every write; it answers
79	// Ok or a typed failure over any input, and its work stays linear.
80	#[hegel::test(test_cases = 512)]
81	fn narinfo_parse_is_total(tc: TestCase) {
82	    let bytes: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(2_000));
83	    let text = String::from_utf8_lossy(&bytes);
84	    let _ = Narinfo::parse(&text);
85	}
86	
87	const NIX32: &[u8] = b"REDACTED";
88	// why: store path names allow letters, digits, and `+-._?=` including the
89	// vowels the base32 alphabet excludes; the two grammars are different.
90	const NAME_CHARS: &[u8] = b"REDACTED._?=";
91	
92	fn draw_letter(tc: &TestCase, alphabet: &[u8]) -> char {
93	    let pick = tc.draw(gs::integers::<u8>());
94	    alphabet[usize::from(pick) % alphabet.len()] as char
95	}
96	
97	fn draw_nix32(tc: &TestCase, len: usize) -> String {
98	    (0..len).map(|_| draw_letter(tc, NIX32)).collect()
99	}
100	
101	fn draw_name(tc: &TestCase, len: usize) -> String {
102	    (0..len.max(1))
103	        .map(|_| draw_letter(tc, NAME_CHARS))
104	        .collect()
105	}
106	
107	// why: the canonical form is what nix verifies. Serialize then parse then
108	// serialize is the identity on the canonical view of any well-formed
109	// document, which is what makes the signing pipeline safe to canonicalize.
110	#[hegel::test(test_cases = 256)]
111	fn narinfo_canonicalization_is_a_fixed_point(tc: TestCase) {
112	    let store_hash = draw_nix32(&tc, 32);
113	    let file_hash = draw_nix32(&tc, 52);
114	    let name = draw_name(&tc, 12);
115	    let ref_count = tc.draw(gs::integers::<usize>().max_value(4));
116	    let refs: Vec<String> = (0..ref_count)
117	        .map(|_| format!("{}-{}", draw_nix32(&tc, 32), draw_name(&tc, 6)))
118	        .collect();
119	    // Deliberately scrambled field order: canonicalization must settle it.
120	    let body = format!(
121	        "References: {}\nNarSize: 123\nURL: nar/{file_hash}.nar.zst\nStorePath: /nix/store/{store_hash}-{name}\nX-Unknown: preserved verbatim\nSig: cache:nhQ==\nCompression: zstd\nNarHash: sha256:{}\n",
122	        refs.join(" "),
123	        draw_nix32(&tc, 52)
124	    );
125	    let parsed = Narinfo::parse(&body).expect("generated documents parse");
126	    let once = parsed.serialize();
127	    let twice = Narinfo::parse(&once)
128	        .expect("canonical form reparses")
129	        .serialize();
130	    assert_eq!(once, twice, "canonicalization is a fixed point");
131	
132	    // Field order in the canonical form is exactly the locked order.
133	    let order: Vec<&str> = once
134	        .lines()
135	        .map(|line| line.split(':').next().expect("a key"))
136	        .collect();
137	    let expected = [
138	        "StorePath",
139	        "URL",
140	        "Compression",
141	        "NarHash",
142	        "NarSize",
143	        "References",
144	        "Sig",
145	        "X-Unknown",
146	    ];
147	    assert_eq!(order, expected);
148	}
149	
150	// why: the fingerprint is the signature input nix reproduces; drift in it
151	// fails `nix store verify` for every artifact cachet signs.
152	#[hegel::test(test_cases = 128)]
153	fn fingerprint_matches_its_recipe(tc: TestCase) {
154	    let store_hash = draw_nix32(&tc, 32);
155	    let name = draw_name(&tc, 12);
156	    let nar_hash = draw_nix32(&tc, 52);
157	    let body = format!(
158	        "StorePath: /nix/store/{store_hash}-{name}\nURL: nar/{}.nar\nNarHash: sha256:{nar_hash}\nNarSize: 1\n",
159	        draw_nix32(&tc, 52)
160	    );
161	    let document = Narinfo::parse(&body).expect("generated documents parse");
162	    assert_eq!(
163	        document.fingerprint(),
164	        format!("1;/nix/store/{store_hash}-{name};sha256:{nar_hash};1;")
165	    );
166	}
167	
168	// why: leases are the collector's only state; the lenient parser must
169	// still refuse the two fields the collector's safety depends on, over
170	// arbitrary JSON.
171	#[hegel::test(test_cases = 256)]
172	fn lease_parse_is_total(tc: TestCase) {
173	    let bytes: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(600));
174	    let text = String::from_utf8_lossy(&bytes);
175	    let _ = cachet_core::lease::LeaseDocument::parse(&text);
176	}
