/**
 * The edge-cache generation.
 *
 * Long `immutable` cache TTLs are only safe because every object's cache key embeds a monotonic
 * generation number (ADR 0012). A destructive sweep bumps it, and every point of presence
 * converges within `GENERATION_EDGE_TTL_SECONDS` — which is the bound Invariant
 * GENERATION-AFTER-SWEEP promises.
 *
 * The number lives in one small bucket object. This module owns its format and the key derivation;
 * reading and writing it is the edge's job.
 *
 * @module
 */

import { EDGE_CACHE_KEY_ORIGIN, GENERATION_DOCUMENT_BYTES_MAX } from '../constants.js';
import { fail, ok, type Result } from '../result.js';
import { generation, nextGeneration, type Generation, type UnixMillis } from '../types.js';

/** What `meta/generation` holds. */
export interface GenerationDocument {
    readonly generation: Generation;
    /** When the sweep that produced this generation finished — operational context only. */
    readonly bumpedAtMs: UnixMillis;
}

/** Serialise the document. Golden-locked: the collector writes it and the read path parses it. */
export function serializeGenerationDocument(document: GenerationDocument): string {
    return `${JSON.stringify({ generation: Number(document.generation), bumpedAtMs: Number(document.bumpedAtMs) })}\n`;
}

/**
 * Parse the document.
 *
 * Defensive despite being our own writing: a half-written or truncated object is a state we can
 * reach through a failed sweep, and the read path must have something safe to do about it. The
 * caller treats a failure as "bypass the edge cache entirely" rather than as generation zero —
 * reusing zero would resurrect cache entries written before the first sweep, which is the
 * staleness the generation exists to prevent.
 */
export function parseGenerationDocument(text: string): Result<GenerationDocument> {
    // A well-formed document is under a hundred bytes; anything larger is not one.
    if (text.length > GENERATION_DOCUMENT_BYTES_MAX) {
        return fail('malformed_narinfo', 'the generation document is implausibly large');
    }

    let parsed: unknown;
    try {
        parsed = JSON.parse(text);
    } catch {
        return fail('malformed_narinfo', 'the generation document is not valid JSON');
    }
    if (typeof parsed !== 'object' || parsed === null) {
        return fail('malformed_narinfo', 'the generation document is not an object');
    }

    const raw = parsed as { generation?: unknown; bumpedAtMs?: unknown };
    if (
        typeof raw.generation !== 'number' ||
        !Number.isSafeInteger(raw.generation) ||
        raw.generation < 0
    ) {
        return fail('malformed_narinfo', 'the generation is not a non-negative integer');
    }
    if (
        typeof raw.bumpedAtMs !== 'number' ||
        !Number.isSafeInteger(raw.bumpedAtMs) ||
        raw.bumpedAtMs < 0
    ) {
        return fail('malformed_narinfo', 'the bump timestamp is not a non-negative integer');
    }

    return ok({ generation: generation(raw.generation), bumpedAtMs: raw.bumpedAtMs as UnixMillis });
}

/** The document a sweep writes after deleting anything (Invariant GENERATION-AFTER-SWEEP). */
export function bumpedGenerationDocument(
    current: Generation,
    nowMs: UnixMillis,
): GenerationDocument {
    return { generation: nextGeneration(current), bumpedAtMs: nowMs };
}

/**
 * The edge-cache key for an object.
 *
 * Built under a fixed internal origin rather than the request's own, so the key is ours and the
 * generation can be part of it. Bumping the generation therefore changes every object's cache key at
 * once, so no point of presence is asked for its stale entries again, and no purge API, credentials,
 * or per-key walk is needed.
 *
 * @example
 * ```ts
 * const key = objectCacheKey(generation(7), '/abc.narinfo');
 * // returns 'https://cachet-edge.invalid/g7/abc.narinfo'
 * ```
 */
export function objectCacheKey(current: Generation, requestPath: string): string {
    const path = requestPath.startsWith('/') ? requestPath : `/${requestPath}`;
    return `${EDGE_CACHE_KEY_ORIGIN}/g${String(Number(current))}${path}`;
}

/**
 * The edge-cache key for the generation document itself.
 *
 * This key sits outside the generation-prefixed space: it is the entry whose short TTL bounds how
 * long a stale generation can be believed, so it cannot be keyed by the value it carries.
 */
export function generationCacheKey(): string {
    return `${EDGE_CACHE_KEY_ORIGIN}/meta/generation`;
}

