/// Resolve the current edge-cache generation: matched through the edge
/// cache (the common case costs a near-free lookup), falling back to the
/// bucket, with the short TTL bounding stale belief. Returns None when the
/// generation cannot be established, and the caller then bypasses the edge
/// cache entirely rather than assuming zero: reusing zero would resurrect
/// entries written before the first sweep, the staleness the generation
/// exists to prevent.
async fn resolve_generation(env: &Env, ctx: &Context) -> Result<Option<u64>> {
    let cache = Cache::default();
    let cache_key = generation_cache_key();
    if let Some(mut cached) = cache.get(&cache_key, true).await? {
        let text = cached.text().await?;
        let Ok(document) = GenerationDocument::parse(&text) else {
            log::alert("generation.cached_document_corrupt");
            return Ok(None);
        };
        return Ok(Some(document.generation));
    }
    let bucket = env.bucket("CACHE_BUCKET")?;
    let document = match bucket.get(GENERATION_OBJECT_KEY).execute().await? {
        Some(object) => {
            let Some(body) = object.body() else { return Ok(None) };
            body.text().await?
        }
        None => GenerationDocument::ZERO.serialize(),
    };
    let Ok(document) = GenerationDocument::parse(&document) else {
        log::alert("generation.document_corrupt");
        return Ok(None);
    };
    let body = document.serialize();
    let cached = apply(Response::ok(body)?, &[("content-type", "application/json".to_string()), ("cache-control", format!("public, max-age={GENERATION_EDGE_TTL_SECONDS}"))])?;
    ctx.wait_until(async move {
        let _ = cache.put(cache_key, cached).await;
    });
    Ok(Some(document.generation))
}
