1	// The workerd lane's driver (docs/testing/workerd.md). Each scenario:
2	// seed workerd's local R2 through the wrangler CLI, boot the built worker
3	// under `wrangler dev --local` on its own port and persistence directory,
4	// and assert over real HTTP. Caching behavior is observable through the
5	// worker's own event log (read.edge_hit, read.bucket_hit, read.miss,
6	// generation.document_corrupt), which wrangler streams on stdout.
7	//
8	// No npm dependencies: node 22's fetch, child_process, and stdlib cover
9	// everything. Usage: node workerd/check.mjs <fixtures dir>
10	
11	import assert from "node:assert/strict";
12	import { spawn, spawnSync } from "node:child_process";
13	import { mkdtemp, readFile, writeFile } from "node:fs/promises";
14	import net from "node:net";
15	import os from "node:os";
16	import path from "node:path";
17	
18	const repoRoot = path.resolve(import.meta.dirname, "..");
19	const configPath = path.join(repoRoot, "workerd", "wrangler.toml");
20	const fixturesDir = path.resolve(
21	  process.argv[2] ?? path.join(repoRoot, "fixtures", "nix-signed"),
22	);
23	
24	const NARINFO_KEY = "qvqa04f0m85m0a6xxnan5vxnwg2jkgl9.narinfo";
25	const NAR_FILE = "11lx23nn3dpc8mqp0ncnm6wqcxs6pfw32bp8n9c1fkafyzjvn16y.nar.zst";
26	const NAR_KEY = `nar/${NAR_FILE}`;
27	const OTHER_NARINFO = "33333333333333333333333333333333.narinfo";
28	
29	const results = [];
30	async function check(name, fn) {
31	  try {
32	    await fn();
33	    results.push(["ok", name]);
34	    process.stdout.write(`ok ${name}\n`);
35	  } catch (failure) {
36	    results.push(["FAIL", `${name}: ${failure.message}`]);
37	    process.stdout.write(`FAIL ${name}: ${failure.message}\n`);
38	  }
39	}
40	
41	function freePort() {
42	  return new Promise((resolve, reject) => {
43	    const probe = net.createServer();
44	    probe.once("error", reject);
45	    probe.listen(0, "127.0.0.1", () => {
46	      const { port } = probe.address();
47	      probe.close(() => resolve(port));
48	    });
49	  });
50	}
51	
52	const settle = () => new Promise((resolve) => setTimeout(resolve, 200));
53	
54	// One scenario per persistence directory: fresh R2, fresh edge cache.
55	async function scenario(name, seed, assertions) {
56	  const persist = await mkdtemp(path.join(os.tmpdir(), "cachet-lane-"));
57	  for (const [key, content] of await seed()) {
58	    const seedFile = path.join(persist, "seed-input");
59	    await writeFile(seedFile, content);
60	    const put = spawnSync(
61	      "wrangler",
62	      [
63	        "r2",
64	        "object",
65	        "put",
66	        `cachet-lane/${key}`,
67	        "--file",
68	        seedFile,
69	        "--local",
70	        "--persist-to",
71	        persist,
72	        "--config",
73	        configPath,
74	      ],
75	      { encoding: "utf8" },
76	    );
77	    if (put.status !== 0) {
78	      throw new Error(`seeding ${key} failed: ${put.stderr}${put.stdout}`);
79	    }
80	  }
81	
82	  const port = await freePort();
83	  const proc = spawn(
84	    "wrangler",
85	    [
86	      "dev",
87	      "--local",
88	      "--port",
89	      String(port),
90	      "--persist-to",
91	      persist,
92	      "--config",
93	      configPath,
94	    ],
95	    { detached: true, stdio: ["ignore", "pipe", "pipe"] },
96	  );
97	  let captured = "";
98	  proc.stdout.on("data", (chunk) => (captured += chunk));
99	  proc.stderr.on("data", (chunk) => (captured += chunk));
100	  const base = `http://127.0.0.1:${port}`;
101	
102	  try {
103	    const deadline = Date.now() + 60_000;
104	    let up = false;
105	    while (Date.now() < deadline) {
106	      try {
107	        const probe = await fetch(`${base}/nix-cache-info`);
108	        if (probe.status === 200) {
109	          up = true;
110	          break;
111	        }
112	      } catch {
113	        // Not listening yet.
