 */
export async function putNarinfo(
    env: CachetEnv,
    hash: StorePathHash,
    request: Request,
): Promise<Response> {
    // why: the body is capped at the narinfo's own limit rather than the NAR one. This route once used
    // UPLOAD_SINGLE_MAX_BYTES — 90 MiB — for a document bounded at NARINFO_BYTES_MAX, so the body was
    // read in full and only then refused by the parser's own length check, 128 times too late. The
    // guard has to precede the read or it is not a guard (docs/design/worker.md §2).
    const length = requireContentLength(request.headers.get('content-length'), NARINFO_BYTES_MAX);
    if (!length.ok) {
        return clientErrorResponse(length.error);
    }

    // Read once and keep the exact bytes: a client verifies a signature over them, so the document
    // is stored as received rather than round-tripped through our serialiser.
    const bodyText = await request.text();
    const narinfo = parseNarinfo(bodyText);
    if (!narinfo.ok) {
        return clientErrorResponse(narinfo.error);
    }

    const nar = await env.CACHE_BUCKET.head(String(narinfo.value.url));
    const decision = decideNarinfoWrite(narinfo.value, hash, nar !== null);
    if (!decision.ok) {
        logEvent('warn', 'write.narinfo_rejected', {
            code: decision.error.code,
            narKey: String(narinfo.value.url),
        });
        return clientErrorResponse(decision.error);
    }

    await env.CACHE_BUCKET.put(String(narinfoKeyForHash(hash)), bodyText);
    logEvent('info', 'write.narinfo_stored', { sizeBytes: bodyText.length });
    return storedResponse();
}

