/// that verifies-false is `Ok(false)`, so callers distinguish broken
/// crypto plumbing from a dishonest token.
pub fn verify_rs256(jwk: &RsaJwk, signing_input: &str, signature: &[u8]) -> Result<bool, JwtError> {
    if jwk.kty != "RSA" {
