1	//! GitHub OIDC at the edge (CLAUDE.md §1): the only write credential. The
2	//! decision policy is cachet-core's; this module does the isolate-local
3	//! JWKS caching, the single refetch on an unknown kid, the stale fallback,
4	//! and the environment plumbing. The JWKS document itself is not trusted
5	//! state: it is transport for public keys, refetched from the issuer's URL
6	//! (a deployment variable, so the workerd lane can substitute a stub).
7	
8	use std::cell::RefCell;
9	
10	use cachet_core::auth::{
11	    OidcConfig, OidcIdentity, decide_jwks, refetch_once_allowed, verify_claims,
12	};
13	use cachet_core::error::ClientError;
14	use cachet_core::types::UnixMillis;
15	use cachet_crypto::rs256::{RsaJwk, decode_jwt, verify_rs256};
16	use worker::{Env, Fetch, Method, Request};
17	
18	use crate::log;
19	
20	/// The JWKS document's shape.
21	#[derive(Debug, serde::Deserialize)]
22	struct JwksDocument {
23	    keys: Vec<RsaJwk>,
24	}
25	
26	// why: workerd runs one worker per isolate on one thread, so a
27	// thread_local cache is exactly the per-isolate cache the design calls
28	// for (10-minute TTL, one refetch on unknown kid, stale fallback).
29	thread_local! {
30	    static JWKS_CACHE: RefCell<Option<(u64, Vec<RsaJwk>)>> = const { RefCell::new(None) };
31	}
32	
33	/// The deployment's OIDC configuration, read from its variables. Missing
34	/// configuration cannot verify anything, so it answers auth_unavailable
35	/// rather than fail open.
36	fn oidc_config(env: &Env) -> cachet_core::error::Result<OidcConfig> {
37	    let orgs = env
38	        .var("CACHET_ORGS")
39	        .map_err(|_| ClientError::AuthUnavailable)?
40	        .to_string();
41	    let audience = env
42	        .var("CACHET_AUDIENCE")
43	        .map_err(|_| ClientError::AuthUnavailable)?
44	        .to_string();
45	    let default_branch_ref = env
46	        .var("CACHET_DEFAULT_BRANCH_REF")
47	        .map_err(|_| ClientError::AuthUnavailable)?
48	        .to_string();
49	    let config = OidcConfig {
50	        orgs: orgs
51	            .split(',')
52	            .map(|org| org.trim().to_string())
53	            .filter(|org| !org.is_empty())
54	            .collect(),
55	        audience,
56	        default_branch_ref,
57	    };
58	    config.validate()?;
59	    Ok(config)
60	}
61	
62	/// Fetch the issuer's JWKS document now.
63	async fn fetch_jwks(env: &Env) -> cachet_core::error::Result<Vec<RsaJwk>> {
64	    let url = env
65	        .var("CACHET_JWKS_URL")
66	        .map_err(|_| ClientError::AuthUnavailable)?
67	        .to_string();
68	    let request = Request::new(&url, Method::Get).map_err(|_| ClientError::AuthUnavailable)?;
69	    let mut response = Fetch::Request(request)
70	        .send()
71	        .await
72	        .map_err(|_| ClientError::AuthUnavailable)?;
73	    if response.status_code() != 200 {
74	        return Err(ClientError::AuthUnavailable);
75	    }
76	    let document: JwksDocument = response
77	        .json()
78	        .await
79	        .map_err(|_| ClientError::AuthUnavailable)?;
80	    Ok(document.keys)
81	}
82	
83	/// Resolve the signing key for `kid`, maintaining the isolate's cache
84	/// policy. Stale fallback is deliberate: a cached document older than its
85	/// TTL is better than an outage ("auth_unavailable" is only for having no
86	/// trustworthy document at all), and the TTL still bounds how long a
87	/// rotated-away key keeps working.
88	async fn jwks_key_for(
89	    env: &Env,
90	    now: UnixMillis,
91	    kid: Option<&str>,
92	) -> cachet_core::error::Result<RsaJwk> {
93	    let cached = JWKS_CACHE.with(|slot| slot.borrow().clone());
94	    let find =
95	        |keys: &[RsaJwk]| kid.and_then(|kid| keys.iter().find(|key| key.kid == kid).cloned());
96	
97	    // (document, whether it was fetched for this request): the flag is
98	    // what the single-refetch-on-unknown-kid rule keys off.
99	    let (mut keys, fresh) = match cached.as_ref().and_then(|(fetched_at_ms, keys)| {
100	        (decide_jwks(Some(*fetched_at_ms), now) == cachet_core::auth::JwksDecision::UseCached)
101	            .then(|| keys.clone())
102	    }) {
103	        Some(keys) => (keys, false),
104	        None => match fetch_jwks(env).await {
105	            Ok(keys) => {
106	                JWKS_CACHE.with(|slot| {
107	                    *slot.borrow_mut() = Some((now.as_u64(), keys.clone()));
108	                });
109	                (keys, true)
110	            }
111	            Err(fresh) => match cached {
112	                Some((_, keys)) => {
113	                    log::event(
114	                        "warn",
115	                        "auth.jwks_fetch_failed_stale_fallback",
116	                        &[("error", format!("{fresh:?}"))],
117	                    );
118	                    (keys, false)
119	                }
120	                None => return Err(fresh),
121	            },
122	        },
123	    };
124	
125	    if let Some(key) = find(&keys) {
126	        return Ok(key);
127	    }
128	    // An unknown kid means the issuer rotated since the cache entry: one
129	    // refetch, never a loop.
130	    if refetch_once_allowed(fresh) {
131	        keys = fetch_jwks(env)
132	            .await
133	            .map_err(|_| ClientError::Unauthorized)?;
134	        JWKS_CACHE.with(|slot| {
135	            *slot.borrow_mut() = Some((now.as_u64(), keys.clone()));
136	        });
137	        if let Some(key) = find(&keys) {
138	            return Ok(key);
139	        }
140	    }
141	    Err(ClientError::Unauthorized)
142	}
143	
144	/// The write-path credential check: bearer, RS256 against the JWKS, claim
145	/// policy. Answers the identity a successful token attests, for the routes
146	/// that bind it (leases pin the repository claims).
147	///
148	/// # Errors
149	///
150	/// [`ClientError::Unauthorized`] for a missing, malformed, forged, or
151	/// expired token; [`ClientError::ForbiddenOrg`] for a valid token outside
152	/// the deployment's orgs; [`ClientError::AuthUnavailable`] when no
153	/// trustworthy JWKS can be had.
154	pub async fn authorize_write(
155	    env: &Env,
156	    now: UnixMillis,
157	    authorization: Option<&str>,
158	) -> cachet_core::error::Result<OidcIdentity> {
159	    let config = oidc_config(env)?;
160	
161	    let token = authorization
162	        .and_then(|header| header.strip_prefix("Bearer "))
163	        .ok_or(ClientError::Unauthorized)?;
164	    let decoded = decode_jwt(token).map_err(|_| ClientError::Unauthorized)?;
165	
166	    let key = jwks_key_for(env, now, decoded.kid.as_deref()).await?;
167	    let verified = verify_rs256(&key, &decoded.signing_input, &decoded.signature)
168	        .map_err(|_| ClientError::Unauthorized)?;
169	    if !verified {
170	        return Err(ClientError::Unauthorized);
171	    }
172	
173	    verify_claims(&decoded.claims, &config, now)
174	}

1	//! Multipart part planning (CLAUDE.md §4, docs/testing/kani.md). The
2	//! upload protocol declares the total byte count up front, and every part
3	//! except the last carries exactly [`UPLOAD_PART_BYTES`]; the server
4	//! verifies completeness against this plan, so client and worker compute
5	//! it from one function.
6	
7	use crate::constants::{COMPLETE_BODY_BYTES_MAX, MULTIPART_PARTS_MAX, UPLOAD_PART_BYTES};
8	use crate::error::{ClientError, Result};
9	use crate::upload_record::UploadRecord;
10	
11	/// One planned part: a one-based part number and its exact byte length.
12	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
13	pub struct Part {
14	    /// One-based part number, as the wire protocol carries it.
15	    pub number: u64,
16	    /// The exact byte length of this part.
17	    pub len: u64,
18	}
19	
20	/// The full plan for one upload.
21	#[derive(Debug, Clone, PartialEq, Eq)]
22	pub struct PartPlan {
23	    /// The declared total byte count of the upload.
24	    pub total_bytes: u64,
25	    /// The parts, in ascending order.
26	    pub parts: Vec<Part>,
27	}
28	
29	/// The arithmetic shape of a plan: how many parts, and how long the last
30	/// one is. Kani proves every law of the plan over this shape alone, so the
31	/// materializing loop below never carries a symbolic bound.
32	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
33	pub struct PlanShape {
34	    /// The part count, between 1 and [`MULTIPART_PARTS_MAX`].
35	    pub count: u64,
36	    /// The byte length of the final part, between 1 and
37	    /// [`UPLOAD_PART_BYTES`].
38	    pub last_len: u64,
39	}
40	
41	/// Compute the shape of the plan for an object of `total_bytes`.
42	///
43	/// # Errors
44	///
45	/// - [`ClientError::LengthRequired`] when the total is zero: the protocol
46	///   requires a declared positive total before any part is accepted.
47	/// - [`ClientError::BodyTooLarge`] when the total exceeds
48	///   [`UPLOAD_PART_BYTES`] times [`MULTIPART_PARTS_MAX`].
49	pub fn plan_shape(total_bytes: u64) -> Result<PlanShape> {
50	    if total_bytes == 0 {
51	        return Err(ClientError::LengthRequired);
52	    }
53	    if total_bytes > UPLOAD_PART_BYTES * MULTIPART_PARTS_MAX {
54	        return Err(ClientError::BodyTooLarge);
55	    }
56	    let full_parts = total_bytes / UPLOAD_PART_BYTES;
57	    let remainder = total_bytes % UPLOAD_PART_BYTES;
58	    Ok(PlanShape {
59	        count: if remainder == 0 {
60	            full_parts
61	        } else {
62	            full_parts + 1
63	        },
64	        last_len: if remainder == 0 {
65	            UPLOAD_PART_BYTES
66	        } else {
67	            remainder
68	        },
69	    })
70	}
71	
72	/// Materialize the plan for an object of `total_bytes`, one part per part
73	/// number in ascending order.
74	///
75	/// # Errors
76	///
77	/// The same failures as [`plan_shape`].
78	pub fn part_plan(total_bytes: u64) -> Result<PartPlan> {
79	    let shape = plan_shape(total_bytes)?;
80	    let mut parts = Vec::with_capacity(usize::try_from(shape.count).expect("count ≤ 1000"));
81	    for n in 1..=shape.count {
82	        let len = if n == shape.count {
83	            shape.last_len
84	        } else {
85	            UPLOAD_PART_BYTES
86	        };
87	        parts.push(Part { number: n, len });
88	    }
89	    debug_assert_eq!(parts.iter().map(|p| p.len).sum::<u64>(), total_bytes);
90	    Ok(PartPlan { total_bytes, parts })
91	}
92	
93	/// The exact size one part must carry, given the plan totals.
94	#[must_use]
95	pub fn expected_part_bytes(total_bytes: u64, expected_parts: u64, part_number: u64) -> u64 {
96	    debug_assert!(part_number >= 1 && part_number <= expected_parts);
97	    if part_number == expected_parts {
98	        total_bytes - (expected_parts - 1) * UPLOAD_PART_BYTES
99	    } else {
100	        UPLOAD_PART_BYTES
101	    }
102	}
103	
104	/// Validate one part before it is stored. The check runs here, per
105	/// request, because R2's own uniform-part rule fires only at completion —
106	/// after every byte has crossed the network. Catching a wrong-sized part
107	/// on arrival costs the client one request, where catching it at
108	/// completion costs the whole upload.
109	///
110	/// # Errors
111	///
112	/// [`ClientError::PartNumberInvalid`] outside `1..=record.expected_parts`;
113	/// [`ClientError::PartSizeMismatch`] when the declared length is not the
114	/// planned size for this part.
115	pub fn check_part(record: &UploadRecord, part_number: u64, content_length: u64) -> Result<()> {
116	    if part_number == 0 || part_number > record.expected_parts {
117	        return Err(ClientError::PartNumberInvalid);
118	    }
119	    let expected = expected_part_bytes(record.total_bytes, record.expected_parts, part_number);
120	    if content_length != expected {
121	        return Err(ClientError::PartSizeMismatch);
122	    }
123	    Ok(())
124	}
125	
126	/// One completed part, as the client reports it in the completion body.
127	#[derive(Debug, Clone, PartialEq, Eq)]
128	pub struct CompletedPart {
129	    /// The one-based part number.
130	    pub number: u64,
131	    /// The checksum R2 returned for the part when it was stored.
132	    pub etag: String,
133	}
134	
135	/// Validate the part list a client sends to complete an upload. Exactly
136	/// the planned parts, once each, in ascending order: both what R2 expects
137	/// and the only list that can reassemble the object the client declared.
138	///
139	/// # Errors
140	///
141	/// [`ClientError::BodyTooLarge`] when the body exceeds
142	/// [`COMPLETE_BODY_BYTES_MAX`]; [`ClientError::CompletePartsMismatch`]
143	/// on any shape violation.
144	pub fn parse_completion_body(text: &str, record: &UploadRecord) -> Result<Vec<CompletedPart>> {
145	    if u64::try_from(text.len()).expect("len fits") > COMPLETE_BODY_BYTES_MAX {
146	        return Err(ClientError::BodyTooLarge);
147	    }
148	    let parsed: serde_json::Value =
149	        serde_json::from_str(text).map_err(|_| ClientError::CompletePartsMismatch)?;
150	    let entries = parsed
151	        .as_array()
152	        .ok_or(ClientError::CompletePartsMismatch)?;
153	    if u64::try_from(entries.len()).expect("len fits") != record.expected_parts {
154	        return Err(ClientError::CompletePartsMismatch);
155	    }
156	    let mut parts = Vec::with_capacity(entries.len());
157	    for (index, entry) in entries.iter().enumerate() {
158	        let number = entry
159	            .get("partNumber")
160	            .and_then(serde_json::Value::as_u64)
161	            .ok_or(ClientError::CompletePartsMismatch)?;
162	        let etag = entry
163	            .get("etag")
164	            .and_then(serde_json::Value::as_str)
165	            .filter(|etag| !etag.is_empty())
166	            .ok_or(ClientError::CompletePartsMismatch)?;
167	        // Ascending and gapless, which also rules out duplicates without a
168	        // second pass.
169	        if number != u64::try_from(index).expect("index fits") + 1 {
170	            return Err(ClientError::CompletePartsMismatch);
171	        }
172	        parts.push(CompletedPart {
173	            number,
174	            etag: etag.to_string(),
175	        });
176	    }
177	    Ok(parts)
178	}
