1	//! ed25519 signing in the nix binary-cache key format
2	//! (`<name>:<base64>`), the custody-critical half of cachet's security
3	//! story: the worker signs a narinfo's fingerprint only after the write-path
4	//! verifier produced it, and the secret itself never leaves this module's
5	//! zeroizing wrapper. Signatures are deterministic by design, so the
6	//! fixture signed by real nix must reproduce exactly here, byte for byte,
7	//! and the golden lane proves it does.
8	
9	use base64::Engine;
10	use ed25519_dalek::Signer;
11	use zeroize::Zeroizing;
12	
13	/// Why a key blob failed to parse.
14	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
15	pub enum KeyError {
16	    /// The text was not `<name>:<base64>`.
17	    Shape,
18	    /// The base64 did not decode.
19	    Base64,
20	    /// The decoded length was not 64 (secret) or 32 (public) bytes.
21	    Length,
22	    /// The secret blob's public half disagrees with its secret half.
23	    MismatchedHalves,
24	}
25	
26	impl core::fmt::Display for KeyError {
27	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
28	        f.write_str(match self {
29	            Self::Shape => "a nix key is <name>:<base64>",
30	            Self::Base64 => "the key blob is not base64",
31	            Self::Length => "the key blob has the wrong length",
32	            Self::MismatchedHalves => "the secret blob's halves disagree",
33	        })
34	    }
35	}
36	
37	impl std::error::Error for KeyError {}
38	
39	/// A parsed nix secret key: the 64-byte secret blob (seed + public half)
40	/// plus the key's name. Signing never needs a generator (ed25519 is
41	/// deterministic), so this type holds bytes, not state.
42	pub struct NixSecretKey {
43	    name: String,
44	    blob: Zeroizing<[u8; 64]>,
45	}
46	
47	impl NixSecretKey {
48	    /// Parse `<name>:<base64(64 bytes)>`.
49	    ///
50	    /// # Errors
51	    ///
52	    /// [`KeyError`] on shape, base64, or length failures, and on the blob's
53	    /// public half disagreeing with the seed half (a corrupt handoff).
54	    pub fn parse(text: &str) -> Result<Self, KeyError> {
55	        let (name, blob64) = text.trim().split_once(':').ok_or(KeyError::Shape)?;
56	        if name.is_empty() {
57	            return Err(KeyError::Shape);
58	        }
59	        let bytes = base64::engine::general_purpose::STANDARD
60	            .decode(blob64)
61	            .map_err(|_| KeyError::Base64)?;
62	        let arr = <[u8; 64]>::try_from(&bytes[..]).map_err(|_| KeyError::Length)?;
63	        let blob = Zeroizing::new(arr);
64	        let signing = ed25519_dalek::SigningKey::from_bytes(
65	            <&[u8; 32]>::try_from(&blob[..32]).expect("slice of 64"),
66	        );
67	        if signing.verifying_key().to_bytes() != blob[32..] {
68	            return Err(KeyError::MismatchedHalves);
69	        }
70	        Ok(Self {
71	            name: name.to_string(),
72	            blob,
73	        })
74	    }
75	
76	    /// Derive a key from a 32-byte seed (as `cachet keygen` produces).
77	    ///
78	    /// # Errors
79	    ///
80	    /// [`KeyError`] only structurally: derivation cannot fail.
81	    pub fn from_seed(name: &str, seed: &[u8; 32]) -> Result<Self, KeyError> {
82	        let signing = ed25519_dalek::SigningKey::from_bytes(seed);
83	        let mut blob = Zeroizing::new([0u8; 64]);
84	        blob[..32].copy_from_slice(seed);
85	        blob[32..].copy_from_slice(&signing.verifying_key().to_bytes());
86	        Ok(Self {
87	            name: name.to_string(),
88	            blob,
89	        })
90	    }
91	
92	    /// The key's name, the `Sig` field's prefix.
93	    pub fn name(&self) -> &str {
94	        &self.name
95	    }
96	
97	    /// The public half in nix's `<name>:<base64(32 bytes)>` format.
98	    pub fn public_key_text(&self) -> String {
99	        let key = ed25519_dalek::VerifyingKey::from_bytes(
100	            <&[u8; 32]>::try_from(&self.blob[32..]).expect("slice of 64"),
101	        )
102	        .expect("the halves were checked at parse");
103	        format!(
104	            "{}:{}",
105	            self.name,
106	            base64::engine::general_purpose::STANDARD.encode(key.to_bytes())
107	        )
108	    }
109	
110	    /// The secret document in nix's `<name>:<base64(64-byte blob)>` form:
111	    /// what operators put into a Secrets Store binding. The blob is the
112	    /// 32-byte seed followed by its public half, matching the documents
113	    /// real nix writes.
114	    pub fn to_secret_text(&self) -> String {
115	        format!(
116	            "{}:{}",
117	            self.name,
118	            base64::engine::general_purpose::STANDARD.encode(self.blob)
119	        )
120	    }
121	
122	    /// Sign a narinfo fingerprint, returning the `Sig` field's value:
123	    /// `<name>:<base64(64-byte signature)>`. Deterministic: the same
124	    /// fingerprint and key always produce the same bytes.
125	    pub fn sign_fingerprint(&self, fingerprint: &str) -> String {
126	        let signing = ed25519_dalek::SigningKey::from_bytes(
127	            <&[u8; 32]>::try_from(&self.blob[..32]).expect("slice of 64"),
128	        );
129	        let signature = signing.sign(fingerprint.as_bytes());
130	        format!(
131	            "{}:{}",
132	            self.name,
133	            base64::engine::general_purpose::STANDARD.encode(signature.to_bytes())
134	        )
135	    }
136	}
137	
138	impl core::fmt::Debug for NixSecretKey {
139	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
140	        // why: secrets never Debug-print their bytes; the name is the only
141	        // permissible surface.
142	        write!(
143	            f,
144	            "NixSecretKey {{ name: {:?}, blob: <redacted> }}",
145	            self.name
146	        )
147	    }
148	}
