    fn secret_never_debugs_bytes() {
        let key = NixSecretKey::parse(SECRET).expect("parses");
        let shown = format!("{key:?}");
        assert!(!shown.contains("Tv1t"), "the blob never prints: {shown}");
        assert!(shown.contains("cachet-fixture-1"));
    }
}

