/**
 * Lease renewal and lease reads, at the edge.
 *
 * This module is all I/O. Which requests may renew, what a lease document contains, and how a listing
 * is bounded all live in `src/core/`; this module writes and reads the objects those decisions
 * authorise.
 *
 * @module
 */

import {
    BUCKET_LIST_PAGE_LIMIT,
    ROOTS_BODY_BYTES_MAX,
    ROOTS_KEY_PREFIX,
    ROOTS_PROJECTS_MAX,
} from '../core/constants.js';
import { requireContentLength } from '../core/routes/write.js';
import type { OidcIdentity } from '../core/auth/oidc.js';
import { ClientError } from '../core/result.js';
import { boundProjectList, buildLeaseRenewal, serializeProjectList } from '../core/routes/roots.js';
import { unixMillis, type ProjectName } from '../core/types.js';
import { leaseKeyForProject, projectFromLeaseKey, serializeLease } from '../core/wire/lease.js';
import type { CachetEnv } from './env.js';
import { logEvent } from './log.js';
import { clientErrorResponse } from './request.js';
import type { WorkerConfig } from './env.js';

/** JSON, uncacheable: a lease changes on every default-branch build. */
function leaseHeaders(): Record<string, string> {
    return { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
}

/**
 * Renew a project's lease.
 *
 * Last write wins. A lease asserts what a project needs now, so a path that has dropped out of the
 * closure stops being protected, and a lease dropping paths this way is the only reason the cache
 * does not grow without bound (ADR 0001).
 */
export async function renewLease(
    env: CachetEnv,
    config: WorkerConfig,
    project: ProjectName,
    identity: OidcIdentity,
    request: Request,
): Promise<Response> {
    // why: the size guard runs before the body is read. `buildLeaseRenewal` checks ROOTS_BODY_BYTES_MAX
    // against the string it is handed, and that check comes too late to stop a 128 MB isolate buffering
    // whatever the edge let through — the edge's own cap is 100 MB. The declared length is refused
    // first, so an oversized renewal costs a comparison (docs/design/worker.md §2, Invariant BOUNDED-WORK).
    const length = requireContentLength(
        request.headers.get('content-length'),
        ROOTS_BODY_BYTES_MAX,
    );
    if (!length.ok) {
        return clientErrorResponse(length.error);
    }

    const lease = buildLeaseRenewal(
        project,
        await request.text(),
        identity,
        config.defaultBranchRef,
        unixMillis(Date.now()),
    );
    if (!lease.ok) {
        logEvent('warn', 'roots.renewal_rejected', {
            project: String(project),
            code: lease.error.code,
        });
        return clientErrorResponse(lease.error);
    }

    await env.CACHE_BUCKET.put(
        leaseKeyForProject(project, ROOTS_KEY_PREFIX),
        serializeLease(lease.value),
    );
    logEvent('info', 'roots.renewed', {
        project: String(project),
        storePaths: lease.value.storePaths.length,
        commitSha: lease.value.commitSha,
    });
    return new Response(null, { status: 204 });
}

/**
 * List the projects holding leases.
 *
 * This listing exists so the verifier can sample what the leases pin without holding an R2 credential
 * (ADR 0015). It paginates with a bounded page count, so a bucket holding more lease documents than
 * the cap is reported as a problem rather than paginated further (Invariant BOUNDED-WORK).
 */
export async function listProjects(env: CachetEnv): Promise<Response> {
    const projects: ProjectName[] = [];
    let cursor: string | undefined;

    // The loop reads at most enough pages to cover the cap, and the bound below reports the overflow
    // rather than silently truncating.
    for (let page = 0; page <= Math.ceil(ROOTS_PROJECTS_MAX / BUCKET_LIST_PAGE_LIMIT); page += 1) {
        const listed = await env.CACHE_BUCKET.list(
            cursor === undefined
                ? { prefix: ROOTS_KEY_PREFIX, limit: BUCKET_LIST_PAGE_LIMIT }
                : { prefix: ROOTS_KEY_PREFIX, limit: BUCKET_LIST_PAGE_LIMIT, cursor },
        );
        for (const object of listed.objects) {
            const project = projectFromLeaseKey(object.key, ROOTS_KEY_PREFIX);
            if (project.ok) {
                projects.push(project.value);
            }
        }
        if (!listed.truncated) {
            break;
        }
        cursor = listed.cursor;
    }

    const bounded = boundProjectList(projects);
    if (!bounded.ok) {
        logEvent('alert', 'roots.too_many_projects', { count: projects.length });
