/**
 * Lease renewal and lease reads.
 *
 * `POST /roots/{project}` is the one route where the branch a token came from matters. Every branch
 * may push store paths — that is what makes a teammate's checkout fast — but only the default branch
 * may keep a closure alive, because otherwise a long-lived experiment branch would pin its
 * dependencies forever. The Worker enforces the branch rule on the server, because the action checks
 * the ref only as a convenience and the Worker's check is the one that decides
 * (Invariant NO-BYTES-WITHOUT-AUTH).
 *
 * @module
 */

import { ROOTS_PROJECTS_MAX } from '../constants.js';
import { requireDefaultBranch } from '../auth/authorize.js';
import type { OidcIdentity } from '../auth/oidc.js';
import { fail, ok, type Result } from '../result.js';
import type { ProjectName, UnixMillis } from '../types.js';
import type { LeaseDocument } from '../wire/lease.js';
import { parseRootsPayload } from '../wire/roots.js';

/**
 * Build the lease a renewal should write.
 *
 * Pure: the caller supplies the verified identity and the current time, and gets back the document to
 * store. Everything that could be forged comes from the token; only the store paths and the
 * installables come from the body, and the store paths are validated.
 *
 * @example
 * ```ts
 * const lease = buildLeaseRenewal(project, bodyText, identity, config.defaultBranchRef, nowMs);
 * if (!lease.ok) return lease;
 * await bucket.put(leaseKey, serializeLease(lease.value));
 * ```
 */
export function buildLeaseRenewal(
    project: ProjectName,
    bodyText: string,
    identity: OidcIdentity,
    defaultBranchRef: string,
    nowMs: UnixMillis,
): Result<LeaseDocument> {
    // Branch first: a request that may not renew should not have its body parsed.
    const branch = requireDefaultBranch(identity, defaultBranchRef);
    if (!branch.ok) {
        return branch;
    }

    const payload = parseRootsPayload(bodyText);
    if (!payload.ok) {
        return payload;
    }

    return ok({
        project,
        renewedAtMs: nowMs,
        repository: identity.repository,
        ref: identity.ref,
        runId: identity.runId,
        commitSha: identity.commitSha,
        installables: payload.value.installables,
        storePaths: payload.value.storePaths,
    });
}

/**
 * Bound a listing of project names.
 *
 * `GET /roots` exists so the verifier can sample what the leases pin without holding an R2 credential
 * (ADR 0015). It is a read, so it is bounded like every other read. A bucket that somehow accumulated
 * more lease documents than this cap is reported as an error rather than served as a truncated page,
 * because a partial listing would make the verifier sample from a subset it could not know was
 * incomplete (Invariant BOUNDED-WORK).
 */
export function boundProjectList(projects: readonly ProjectName[]): Result<readonly ProjectName[]> {
    if (projects.length > ROOTS_PROJECTS_MAX) {
        return fail(
            'body_too_large',
            `more than ${String(ROOTS_PROJECTS_MAX)} projects hold leases`,
        );
    }
    return ok(projects);
}

/** The JSON body `GET /roots` returns. */
export function serializeProjectList(projects: readonly ProjectName[]): string {
    return `${JSON.stringify({ projects: projects.map(String) }, undefined, 2)}\n`;
}

