    /// to bind without re-reading it.
    Session { login: String },
}

impl ReadIdentity {
    /// The login whichever route the credential came through.
    pub fn login(&self) -> &str {
        match self {
            Self::Token { login } | Self::Session { login } => login,
        }
    }
