1	//! Lease renewal and lease reads: the routes under `/roots`. I/O only
2	//! here: who may renew, what the document contains, and how the listing
3	//! is bounded are cachet-core's decisions; this module performs the bucket
4	//! operations they authorize.
5	
6	use cachet_core::auth::OidcConfig;
7	use cachet_core::error::ClientError;
8	use cachet_core::keys::{lease_key_for_project, project_from_lease_key};
9	use cachet_core::roots::{bound_project_list, build_lease_renewal, serialize_project_list};
10	use cachet_core::types::{ProjectName, UnixMillis};
11	use cachet_core::constants::{BUCKET_LIST_PAGE_LIMIT, ROOTS_BODY_BYTES_MAX, ROOTS_PROJECTS_MAX};
12	use cachet_core::write::require_content_length;
13	use worker::{Env, Request, Response, Result};
14	
15	use crate::{error, log};
16	
17	/// JSON, uncacheable: a lease changes on every default-branch build.
18	fn lease_headers() -> Result<worker::Headers> {
19	    let headers = worker::Headers::new();
20	    headers.set("content-type", "application/json")?;
21	    headers.set("cache-control", "no-store")?;
22	    Ok(headers)
23	}
24	
25	/// Renew a project's lease: a typed answer for every refusal, a 204 for a
26	/// stored renewal. Last write wins by design — a lease asserts what a
27	/// project needs now, and a path dropping out of the closure is the only
28	/// reason the cache stays bounded.
29	pub async fn renew_lease(
30	    env: &Env,
31	    config: &OidcConfig,
32	    identity: &cachet_core::auth::OidcIdentity,
33	    project: &ProjectName,
34	    now: UnixMillis,
35	    mut req: Request,
36	) -> Result<Response> {
37	    let _length = match require_content_length(
38	        req.headers().get("content-length")?.as_deref(),
39	        ROOTS_BODY_BYTES_MAX,
40	    ) {
41	        Ok(length) => length,
42	        Err(code) => return error::problem_response(code),
43	    };
44	    let body_text = req.text().await.map_err(|_| ClientError::MalformedRoots);
45	    let body_text = match body_text {
46	        Ok(text) => text,
47	        Err(code) => return error::problem_response(code),
48	    };
49	    let lease = match build_lease_renewal(project, &body_text, identity, config, now) {
50	        Ok(lease) => lease,
51	        Err(code) => {
52	            log::event(
53	                "warn",
54	                "roots.renewal_rejected",
55	                &[
56	                    ("project", project.as_str().to_string()),
57	                    ("code", code.code().to_string()),
58	                ],
59	            );
60	            return error::problem_response(code);
61	        }
62	    };
63	    match env
64	        .bucket("CACHE_BUCKET")?
65	        .put(lease_key_for_project(project), lease.serialize())
66	        .execute()
67	        .await
68	    {
69	        Ok(_) => {
70	            log::event(
71	                "info",
72	                "roots.renewed",
73	                &[
74	                    ("project", project.as_str().to_string()),
75	                    ("storePaths", lease.store_paths.len().to_string()),
76	                    ("commitSha", lease.commit_sha.clone()),
77	                ],
78	            );
79	            Ok(Response::empty()?.with_status(204))
80	        }
81	        Err(failure) => {
82	            log::event(
83	                "error",
84	                "roots.store_failed",
85	                &[("error", failure.to_string())],
86	            );
87	            error::problem_response(ClientError::StorageUnavailable)
88	        }
89	    }
90	}
91	
92	/// List the projects holding leases, bounded and complete or refused.
93	/// The listing paginates with a bounded page count: a bucket past the cap
94	/// is reported as an overflow rather than silently truncated, because a
95	/// partial list is a wrong answer acting like a right one.
96	pub async fn list_projects(env: &Env) -> Result<Response> {
97	    let bucket = env.bucket("CACHE_BUCKET")?;
98	    let mut projects: Vec<ProjectName> = Vec::new();
99	    let mut cursor: Option<String> = None;
100	    // One page of slack past the cap: the bound below, not this loop, is
101	    // the final word on "too many".
102	    let pages = ROOTS_PROJECTS_MAX / BUCKET_LIST_PAGE_LIMIT + 1;
103	    for _page in 0..=pages {
104	        let mut builder = bucket
105	            .list()
106	            .prefix(cachet_core::constants::ROOTS_KEY_PREFIX)
107	            .limit(u32::try_from(BUCKET_LIST_PAGE_LIMIT).expect("the page limit fits u32"));
108	        if let Some(cursor) = &cursor {
109	            builder = builder.cursor(cursor);
110	        }
111	        let listed = match builder.execute().await {
112	            Ok(listed) => listed,
113	            Err(failure) => {
114	                log::event(
115	                    "error",
116	                    "roots.list_failed",
117	                    &[("error", failure.to_string())],
118	                );
119	                return error::problem_response(ClientError::StorageUnavailable);
120	            }
121	        };
122	        for object in listed.objects() {
123	            if let Ok(project) = project_from_lease_key(&object.key()) {
124	                projects.push(project);
125	            }
126	        }
127	        if !listed.truncated() {
128	            break;
129	        }
130	        cursor = listed.cursor();
131	    }
132	    if let Err(code) = bound_project_list(&projects) {
133	        log::alert("roots.too_many_projects");
134	        return error::problem_response(code);
135	    }
136	    let body = serialize_project_list(&projects);
137	    Ok(Response::ok(body)?.with_headers(lease_headers()?))
138	}
139	
140	/// Serve one lease document verbatim.
141	pub async fn read_lease(env: &Env, project: &ProjectName) -> Result<Response> {
142	    let bucket = env.bucket("CACHE_BUCKET")?;
143	    match bucket
144	        .get(lease_key_for_project(project))
145	        .execute()
146	        .await?
147	    {
148	        None => error::problem_response(ClientError::NotFound),
149	        Some(object) => {
150	            let Some(body) = object.body() else {
151	                return error::problem_response(ClientError::StorageUnavailable);
152	            };
153	            let text = body.text().await?;
154	            Ok(Response::ok(text)?.with_headers(lease_headers()?))
155	        }
156	    }
157	}

