//! Lease renewal and lease reads: the routes under `/roots`. I/O only
//! here: who may renew, what the document contains, and how the listing
//! is bounded are cachet-core's decisions; this module performs the bucket
//! operations they authorize.

use cachet_core::auth::OidcConfig;
use cachet_core::error::ClientError;
use cachet_core::keys::{lease_key_for_project, project_from_lease_key};
use cachet_core::roots::{bound_project_list, build_lease_renewal, serialize_project_list};
use cachet_core::types::{ProjectName, UnixMillis};
use cachet_core::constants::{BUCKET_LIST_PAGE_LIMIT, ROOTS_BODY_BYTES_MAX, ROOTS_PROJECTS_MAX};
use cachet_core::write::require_content_length;
use worker::{Env, Request, Response, Result};

use crate::{error, log};

/// JSON, uncacheable: a lease changes on every default-branch build.
fn lease_headers() -> Result<worker::Headers> {
    let headers = worker::Headers::new();
    headers.set("content-type", "application/json")?;
    headers.set("cache-control", "no-store")?;
    Ok(headers)
}

/// Renew a project's lease: a typed answer for every refusal, a 204 for a
/// stored renewal. Last write wins by design — a lease asserts what a
/// project needs now, and a path dropping out of the closure is the only
/// reason the cache stays bounded.
pub async fn renew_lease(
    env: &Env,
    config: &OidcConfig,
    identity: &cachet_core::auth::OidcIdentity,
    project: &ProjectName,
    now: UnixMillis,
    mut req: Request,
) -> Result<Response> {
    let _length = match require_content_length(
        req.headers().get("content-length")?.as_deref(),
        ROOTS_BODY_BYTES_MAX,
    ) {
        Ok(length) => length,
        Err(code) => return error::problem_response(code),
    };
    let body_text = req.text().await.map_err(|_| ClientError::MalformedRoots);
    let body_text = match body_text {
        Ok(text) => text,
        Err(code) => return error::problem_response(code),
    };
    let lease = match build_lease_renewal(project, &body_text, identity, config, now) {
        Ok(lease) => lease,
        Err(code) => {
            log::event(
                "warn",
                "roots.renewal_rejected",
                &[
                    ("project", project.as_str().to_string()),
                    ("code", code.code().to_string()),
                ],
            );
            return error::problem_response(code);
        }
    };
    match env
        .bucket("CACHE_BUCKET")?
        .put(lease_key_for_project(project), lease.serialize())
        .execute()
        .await
    {
        Ok(_) => {
            log::event(
                "info",
                "roots.renewed",
                &[
                    ("project", project.as_str().to_string()),
                    ("storePaths", lease.store_paths.len().to_string()),
                    ("commitSha", lease.commit_sha.clone()),
                ],
            );
            Ok(Response::empty()?.with_status(204))
        }
        Err(failure) => {
            log::event(
                "error",
                "roots.store_failed",
                &[("error", failure.to_string())],
            );
            error::problem_response(ClientError::StorageUnavailable)
        }
    }
}

/// List the projects holding leases, bounded and complete or refused.
/// The listing paginates with a bounded page count: a bucket past the cap
/// is reported as an overflow rather than silently truncated, because a
/// partial list is a wrong answer acting like a right one.
pub async fn list_projects(env: &Env) -> Result<Response> {
    let bucket = env.bucket("CACHE_BUCKET")?;
    let mut projects: Vec<ProjectName> = Vec::new();
    let mut cursor: Option<String> = None;
    // One page of slack past the cap: the bound below, not this loop, is
    // the final word on "too many".
    let pages = ROOTS_PROJECTS_MAX / BUCKET_LIST_PAGE_LIMIT + 1;
    for _page in 0..=pages {
        let mut builder = bucket
            .list()
            .prefix(cachet_core::constants::ROOTS_KEY_PREFIX)
            .limit(u32::try_from(BUCKET_LIST_PAGE_LIMIT).expect("the page limit fits u32"));
        if let Some(cursor) = &cursor {
            builder = builder.cursor(cursor);
        }
        let listed = match builder.execute().await {
            Ok(listed) => listed,
            Err(failure) => {
                log::event(
                    "error",
                    "roots.list_failed",
                    &[("error", failure.to_string())],
                );
                return error::problem_response(ClientError::StorageUnavailable);
            }
        };
        for object in listed.objects() {
            if let Ok(project) = project_from_lease_key(&object.key()) {
                projects.push(project);
            }
        }
        if !listed.truncated() {
            break;
        }
        cursor = listed.cursor();
    }
    if let Err(code) = bound_project_list(&projects) {
        log::alert("roots.too_many_projects");
        return error::problem_response(code);
    }
    let body = serialize_project_list(&projects);
    Ok(Response::ok(body)?.with_headers(lease_headers()?))
}

/// Serve one lease document verbatim.
pub async fn read_lease(env: &Env, project: &ProjectName) -> Result<Response> {
    let bucket = env.bucket("CACHE_BUCKET")?;
    match bucket
        .get(lease_key_for_project(project))
        .execute()
        .await?
    {
        None => error::problem_response(ClientError::NotFound),
        Some(object) => {
            let Some(body) = object.body() else {
                return error::problem_response(ClientError::StorageUnavailable);
            };
            let text = body.text().await?;
            Ok(Response::ok(text)?.with_headers(lease_headers()?))
        }
    }
}

//! `/api/public/config`: the one unauthenticated JSON document. The CLI
//! and the later SPA discover the deployment's OAuth client id, orgs,
//! host, and public signing key here, so nothing the client needs ever
//! rides in a secret channel it does not yet have.

use cachet_core::error::ClientError;
use cachet_crypto::ed25519::NixSecretKey;
use worker::{Env, Response};

use crate::{auth, log};

/// Serve the public configuration. The signing key's public half is
/// computed from the secret binding: the deployment answers from its own
/// custody rather than from a second copy that could drift.
pub fn public_config(env: &Env) -> worker::Result<Response> {
    let config = match auth::oidc_config(env) {
        Ok(config) => config,
        Err(code) => return crate::error::problem_response(code),
    };
    let client_id = match env.var("CACHET_OAUTH_CLIENT_ID") {
        Ok(client_id) => client_id.to_string(),
        Err(_) => return crate::error::problem_response(ClientError::AuthUnavailable),
    };
    let host = match env.var("CACHET_HOST") {
        Ok(host) => host.to_string(),
        Err(_) => return crate::error::problem_response(ClientError::AuthUnavailable),
    };
    let public_key = match env.secret("CACHET_SIGNING_KEY") {
        Ok(secret) => match NixSecretKey::parse(&secret.to_string()) {
            Ok(key) => key.public_key_text(),
            Err(failure) => {
                crate::log::event(
                    "error",
                    "api.signing_key_corrupt",
                    &[("error", format!("{failure:?}"))],
                );
                return crate::error::problem_response(ClientError::AuthUnavailable);
            }
        },
        Err(_) => return crate::error::problem_response(ClientError::AuthUnavailable),
    };
    log::event("info", "api.public_config", &[]);
    let body = serde_json::json!({
        "oauthClientId": client_id,
        "orgs": config.orgs,
        "host": host,
        "publicKey": public_key,
    })
    .to_string();
    let headers = worker::Headers::new();
    headers.set("content-type", "application/json")?;
    headers.set("cache-control", "no-store")?;
    Ok(Response::ok(body)?.with_headers(headers))
}

//! Read authorization at the edge: a device-flow GitHub token validated
//! against the GitHub API and verdict-cached in KV, or a browser session
//! resolved from its cookie. Two facts guide the cut. Verdicts cache by
//! the token's sha256, so the token itself never persists, and admits
//! outlast denials (600s to 60s) because credential revocation must
//! converge in minutes while a fresh member must not bounce on the API.
//! And the API itself is a deployment variable: transport configuration,
//! so the workerd lane can substitute a stub without weakening any check.

use cachet_core::auth::{SessionRecord, Verdict, session_live, verdict_fresh, verdict_ttl_ms};
use cachet_core::constants::{SESSION_COOKIE_NAME, SESSION_KEY_PREFIX, VERDICT_KEY_PREFIX};
use cachet_core::error::{ClientError, Result};
use cachet_core::types::UnixMillis;
use cachet_crypto::sha256::{hex_digest, sha256};
use base64ct::Encoding as _;
use worker::{Env, Fetch, Headers, Method, Request};

use crate::log;

/// The KV binding for verdicts, sessions, and OAuth state.
pub(super) const KV_BINDING: &str = "CACHET_KV";

/// The read-time identity: who the request authenticates as, and how.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ReadIdentity {
    /// A validated device-flow GitHub token.
    Token { login: String },
    /// A live browser session. The session id is carried for admin routes
    /// to bind without re-reading it.
    Session { login: String },
}

/// A GitHub API answer for one membership query.
#[derive(Debug, serde::Deserialize)]
struct Membership {
    state: String,
}

/// The /user answer's login.
#[derive(Debug, serde::Deserialize)]
struct GitHubUser {
    login: String,
}

fn github_api_url(env: &Env) -> Result<String> {
    env.var("CACHET_GITHUB_API_URL")
        .map_err(|_| ClientError::AuthUnavailable)
        .map(|value| value.to_string())
}

/// One GET to the GitHub API with the lane-wide headers.
async fn github_get(env: &Env, token: &str, path: &str) -> Result<(u16, String)> {
    let base = github_api_url(env)?;
    let headers = Headers::new();
    let _ = headers.set("authorization", &format!("Bearer {token}"));
    let _ = headers.set("accept", "application/vnd.github+json");
    let _ = headers.set("user-agent", "cachet-worker/0.0.1");
    let _ = headers.set("x-github-api-version", "2022-11-28");
    let mut request_init = worker::RequestInit::new();
    request_init.with_method(Method::Get);
    request_init.headers.clone_from(&headers);
    let request = Request::new_with_init(&format!("{base}{path}"), &request_init)
        .map_err(|_| ClientError::AuthUnavailable)?;
    let mut response = Fetch::Request(request)
        .send()
        .await
        .map_err(|_| ClientError::AuthUnavailable)?;
    let status = response.status_code();
    let text = response
        .text()
        .await
        .map_err(|_| ClientError::AuthUnavailable)?;
    Ok((status, text))
}

/// Ask the GitHub API for the login and org membership of `token`.
/// Returns the verdict to cache. API outage is never a verdict: it maps
/// to auth_unavailable rather than a denial, so a client is told to
/// retry, not that it is forbidden.
async fn check_github_token(env: &Env, now: UnixMillis, token: &str) -> Result<Verdict> {
    let (status, body) = github_get(env, token, "/user").await?;
    if status != 200 {
        return Ok(Verdict {
            login: String::new(),
            org_member: false,
            checked_at_ms: now.as_u64(),
        });
    }
    let user: GitHubUser =
        serde_json::from_str(&body).map_err(|_| ClientError::AuthUnavailable)?;
    let config = crate::auth::oidc_config(env)?;
    for org in &config.orgs {
        let (membership_status, membership_body) = github_get(
            env,
            token,
            &format!("/orgs/{org}/memberships/{}", user.login),
        )
        .await?;
        if membership_status == 200 {
            let membership: Membership =
                serde_json::from_str(&membership_body).map_err(|_| ClientError::AuthUnavailable)?;
            if membership.state == "active" {
                return Ok(Verdict {
                    login: user.login,
                    org_member: true,
                    checked_at_ms: now.as_u64(),
                });
            }
        }
    }
    Ok(Verdict {
        login: user.login,
        org_member: false,
        checked_at_ms: now.as_u64(),
    })
}

/// Cache-write one verdict, with the admission or denial TTL.
async fn cache_verdict(kv: &worker::kv::KvStore, digest_hex: &str, verdict: &Verdict) {
    let ttl_seconds = verdict_ttl_ms(verdict.org_member) / 1_000;
    let text = match serde_json::to_string(verdict) {
        Ok(text) => text,
        Err(failure) => {
            log::event(
                "warn",
                "verdict.serialize_failed",
                &[("error", failure.to_string())],
            );
            return;
        }
    };
    if let Ok(builder) = kv.put(
        &format!("{VERDICT_KEY_PREFIX}{digest_hex}"),
        text,
    )
    .map(|builder| builder.expiration_ttl(ttl_seconds))
    {
        if let Err(failure) = builder.execute().await {
            log::event(
                "warn",
                "verdict.cache_write_failed",
                &[("error", failure.to_string())],
            );
        }
    }
}

/// Resolve a device-flow token: sha256 → KV verdict → GitHub on a miss.
async fn resolve_token(env: &Env, now: UnixMillis, token: &str) -> Result<ReadIdentity> {
    let digest_hex = hex_digest(&sha256(token.as_bytes()));
    let kv = env
        .kv(KV_BINDING)
        .map_err(|_| ClientError::AuthUnavailable)?;
    if let Ok(Some(verdict)) = kv
        .get(&format!("{VERDICT_KEY_PREFIX}{digest_hex}"))
        .json::<Verdict>()
        .await
    {
        if verdict_fresh(&verdict, now) {
            return if verdict.org_member {
                Ok(ReadIdentity::Token {
                    login: verdict.login,
                })
            } else {
                Err(ClientError::Unauthorized)
            };
        }
    }
    let verdict = check_github_token(env, now, token).await?;
    cache_verdict(&kv, &digest_hex, &verdict).await;
    if verdict.org_member {
        Ok(ReadIdentity::Token {
            login: verdict.login,
        })
    } else {
        Err(ClientError::Unauthorized)
    }
}

/// Resolve the session cookie: `sess/{id}` in KV, live by absolute age.
async fn resolve_session(env: &Env, now: UnixMillis, session_id: &str) -> Result<ReadIdentity> {
    if session_id.len() > 256 {
        return Err(ClientError::Unauthorized);
    }
    let kv = env
        .kv(KV_BINDING)
        .map_err(|_| ClientError::AuthUnavailable)?;
    let Some(record) = kv
        .get(&format!("{SESSION_KEY_PREFIX}{session_id}"))
        .json::<SessionRecord>()
        .await
        .map_err(|_| ClientError::AuthUnavailable)?
    else {
        return Err(ClientError::Unauthorized);
    };
    if !session_live(record.created_at_ms, now) {
        return Err(ClientError::Unauthorized);
    }
    Ok(ReadIdentity::Session { login: record.login })
}

/// Pull a session id off a Cookie header, if one carries it.
pub(super) fn session_id_from(cookie_header: Option<&str>) -> Option<String> {
    let header = cookie_header?;
    for part in header.split(';') {
        let part = part.trim();
        if let Some((name, value)) = part.split_once('=') {
            if name == SESSION_COOKIE_NAME {
                return Some(value.to_string());
            }
        }
    }
    None
}

/// Resolve read authorization: token first (it can carry an explicit
/// answer), then the session cookie. A deployment with neither resolves
/// nothing, and the answer is 401.
///
/// # Errors
///
/// [`ClientError::Unauthorized`] for a missing or unusable credential;
/// [`ClientError::AuthUnavailable`] when a backend cannot answer.
pub async fn authorize_read(env: &Env, now: UnixMillis, req: &Request) -> Result<ReadIdentity> {
    let headers = req.headers();
    let authorization = headers
        .get("authorization")
        .map_err(|_| ClientError::MalformedAuth)?;
    if let Some(token) = authorization.as_deref().and_then(|header| {
        header
            .strip_prefix("Bearer ")
            .map(ToString::to_string)
            .or_else(|| basic_password(header))
    }) {
        return resolve_token(env, now, &token).await;
    }
    let cookie = headers
        .get("cookie")
        .map_err(|_| ClientError::MalformedAuth)?;
    if let Some(session_id) = session_id_from(cookie.as_deref()) {
        return resolve_session(env, now, &session_id).await;
    }
    Err(ClientError::Unauthorized)
}

/// The password half of `Authorization: Basic base64(user:password)`: the
/// GitHub token arrives as the password because netrc clients speak basic
/// auth, never as a Bearer scheme.
fn basic_password(header: &str) -> Option<String> {
    let encoded = header.strip_prefix("Basic ")?.trim();
    let decoded = base64ct::Base64::decode_vec(encoded).ok()?;
    let text = String::from_utf8(decoded).ok()?;
    text.split_once(':')
        .map(|(_, password)| password.to_string())
        .filter(|password| !password.is_empty())
}

