      [
        "r2",
        "object",
        "put",
        `cachet-lane/${key}`,
        "--file",
        seedFile,
        "--local",
        "--persist-to",
        persist,
        "--config",
        configPath,
      ],
      { encoding: "utf8" },
    );
    if (put.status !== 0) {
      throw new Error(`seeding ${key} failed: ${put.stderr}${put.stdout}`);
    }
  }

  const port = await freePort();
  const proc = spawn(
    "wrangler",
