```rust
//! The browser OAuth flow's pure decisions: what the login redirect
//! carries, what the callback must present, and the cookie strings.

use base64ct::{Base64UrlUnpadded, Encoding};
use crate::constants::{OAUTH_STATE_TTL_MS, SESSION_COOKIE_NAME, SESSION_TTL_MS};
use crate::error::{ClientError, Result};
use crate::types::UnixMillis;

/// The scope the login asks for: the membership read the verdict needs.
pub const OAUTH_SCOPE: &str = "read:org read:user";

/// Sixteen random bytes as the state and session id alphabet: 128 bits is
/// unguessable and base64url keeps either one cookie-safe.
pub fn id_from_random(random: &[u8; 16]) -> String {
    Base64UrlUnpadded::encode_string(random)
}

/// The GitHub authorize URL the login route redirects to.
pub fn authorize_url(web_base: &str, client_id: &str, redirect_uri: &str, state: &str) -> String {
    format!(
        "{web_base}/login/oauth/authorize?client_id={}&redirect_uri={}&scope={}&state={}",
        encode_query(client_id),
        encode_query(redirect_uri),
        encode_query(OAUTH_SCOPE),
        encode_query(state),
    )
}

/// RFC 3986 unreserved pass-through for query parameters: GitHub's
/// callback matching is exact-string, so the encoding must be minimal
/// and total.
fn encode_query(value: &str) -> String { ... percent-encode non-unreserved ... }

/// The callback's two query parameters.
pub struct CallbackParams { pub code: String, pub state: String }

pub fn parse_callback_query(query: &str) -> Result<CallbackParams> {
    // key=value&key=value, percent-decoded
    let mut code = None; let mut state = None;
    for pair in query.split('&') {
        let Some((k, v)) = pair.split_once('=') else { continue };
        match k { "code" => code = Some(decode_query(v)?), "state" => state = Some(decode_query(v)?), _ => {} }
    }
    match (code, state) {
        (Some(code), Some(state)) if !code.is_empty() && !state.is_empty() => Ok(CallbackParams { code, state }),
        _ => Err(ClientError::MalformedOAuth),
    }
}

