//! Lease renewal and lease reads (CLAUDE.md §1, §9). `POST /roots/{project}`
//! is the one route where the branch a token came from matters: every
//! branch may push store paths, because a teammate's checkout should be
//! fast, but only the default branch may keep a closure alive, or a
//! long-lived experiment branch would pin its dependencies forever. The
//! worker enforces the branch rule here, where the answer is decided,
//! because the action checks its own ref only as a convenience.
//!
//! Two more gates sit beside it (ADR 0017): the project a renewal names
//! must equal the token's repository claim, so one repo's CI can never
//! overwrite another repo's lease, and provenance comes only from the
//! verified token, never from the body.

use crate::auth::{OidcConfig, OidcIdentity, require_default_branch, require_project_binding};
use crate::constants::ROOTS_PROJECTS_MAX;
use crate::error::{ClientError, Result};
use crate::lease::LeaseDocument;
use crate::roots_payload::parse_roots_payload;
use crate::types::{ProjectName, UnixMillis};

/// Build the lease a renewal should write. The branch gate and the
/// project binding run before the body is even parsed: a request that may
/// not renew should not have its bytes examined.
///
/// # Errors
///
/// [`ClientError::ForbiddenRef`] off the default branch,
/// [`ClientError::ForbiddenProject`] when the project is not the token's
/// repository, [`ClientError::MalformedRoots`] on an unparsable payload,
/// [`ClientError::BodyTooLarge`] on an over-cap payload.
pub fn build_lease_renewal(
    project: &ProjectName,
    body_text: &str,
    identity: &OidcIdentity,
    config: &OidcConfig,
    now: UnixMillis,
) -> Result<LeaseDocument> {
    require_default_branch(identity, config)?;
    require_project_binding(identity, project)?;
    let payload = parse_roots_payload(body_text)?;
    Ok(LeaseDocument {
        project: project.as_str().to_string(),
        renewed_at_ms: now.as_u64(),
        repository: identity.repository.clone(),
        ref_: identity.ref_.clone(),
        run_id: identity.run_id.clone(),
        commit_sha: identity.sha.clone(),
        installables: payload.installables,
        store_paths: payload.store_paths,
    })
}

/// Bound a listing of project names. `GET /roots` is a read, so it carries
/// the whole answer or nothing: a bucket holding more leases than the cap
/// is a state to report, because a partial listing would make a reviewer
/// sample from a subset they could not know was incomplete.
///
/// # Errors
///
/// [`ClientError::BodyTooLarge`] when the listing exceeds
/// [`ROOTS_PROJECTS_MAX`].
pub fn bound_project_list(projects: &[ProjectName]) -> Result<()> {
    if projects.len() > ROOTS_PROJECTS_MAX {
        return Err(ClientError::BodyTooLarge);
    }
    Ok(())
}

/// The JSON body `GET /roots` returns: two-space indent, trailing newline,
/// names in listing order (which is bucket order, which is sorted).
#[must_use]
pub fn serialize_project_list(projects: &[ProjectName]) -> String {
    #[derive(serde::Serialize)]
    struct ProjectList {
        projects: Vec<String>,
    }
    let list = ProjectList {
        projects: projects
            .iter()
            .map(|project| project.as_str().to_string())
            .collect(),
    };
    let mut body = serde_json::to_string_pretty(&list).expect("string fields");
    body.push('\n');
    body
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config() -> OidcConfig {
        OidcConfig {
            orgs: vec!["lane-org".to_string()],
            audience: "cachet-test".to_string(),
            default_branch_ref: "refs/heads/main".to_string(),
        }
    }

    fn identity() -> OidcIdentity {
        OidcIdentity {
            repository: "lane-org/lane-repo".to_string(),
            repository_owner: "lane-org".to_string(),
            ref_: "refs/heads/main".to_string(),
            run_id: "41".to_string(),
            sha: "abc".to_string(),
        }
    }

    fn payload() -> String {
        serde_json::json!({
            "installables": [".#devShells.aarch64-darwin.default"],
            "storePaths": ["/nix/store/REDACTED.2"],
        })
        .to_string()
    }

    #[test]
    fn the_renewal_carries_only_verified_provenance() {
        let lease = build_lease_renewal(
            &ProjectName::parse("lane-org-lane-repo").expect("valid"),
            &payload(),
            &identity(),
            &config(),
            UnixMillis::new(1_780_000_000_000),
        )
        .expect("the contract builds");
        assert_eq!(lease.repository, "lane-org/lane-repo");
        assert_eq!(lease.ref_, "refs/heads/main");
        assert_eq!(lease.renewed_at_ms, 1_780_000_000_000);
    }

    #[test]
    fn off_branch_renewals_are_forbidden_ref() {
        let mut stray = identity();
        stray.ref_ = "refs/heads/feature".to_string();
        assert_eq!(
            build_lease_renewal(
                &ProjectName::parse("lane-org-lane-repo").expect("valid"),
                &payload(),
                &stray,
                &config(),
                UnixMillis::new(1),
            ),
            Err(ClientError::ForbiddenRef)
        );
    }

    // why: ADR 0017. The previous worker had none of this check: any CI in
    // the org could overwrite any project's lease; the binding makes a
    // lease's project equal to the token's repository, verified.
    #[test]
    fn cross_repo_renewals_are_forbidden_project() {
        assert_eq!(
            build_lease_renewal(
                &ProjectName::parse("lane-org-their-repo").expect("valid"),
                &payload(),
                &identity(),
                &config(),
                UnixMillis::new(1),
            ),
            Err(ClientError::ForbiddenProject)
        );
    }

    #[test]
    fn the_branch_gate_runs_before_the_body() {
        let mut stray = identity();
        stray.ref_ = "refs/heads/feature".to_string();
        assert_eq!(
            build_lease_renewal(
                &ProjectName::parse("lane-org-lane-repo").expect("valid"),
                "not json at all",
                &stray,
                &config(),
                UnixMillis::new(1),
            ),
            Err(ClientError::ForbiddenRef),
            "a bad body behind a bad branch is reported as the branch"
        );
    }

    #[test]
    fn the_listing_bound_is_a_total_answer_or_nothing() {
        let within: Vec<ProjectName> = (0..4)
            .map(|i| ProjectName::parse(&format!("p{i}")).expect("valid"))
            .collect();
        assert!(bound_project_list(&within).is_ok());
        let too_many: Vec<ProjectName> = (0..=ROOTS_PROJECTS_MAX)
            .map(|i| ProjectName::parse(&format!("p{i}")).expect("valid"))
            .collect();
        assert_eq!(
            bound_project_list(&too_many),
            Err(ClientError::BodyTooLarge)
        );
    }
}

//! Lease renewal and lease reads: the routes under `/roots`. I/O only
//! here: who may renew, what the document contains, and how the listing
//! is bounded are cachet-core's decisions; this module performs the bucket
//! operations they authorize.

use cachet_core::auth::OidcConfig;
use cachet_core::constants::{BUCKET_LIST_PAGE_LIMIT, ROOTS_BODY_BYTES_MAX, ROOTS_PROJECTS_MAX};
use cachet_core::error::ClientError;
use cachet_core::keys::{lease_key_for_project, project_from_lease_key};
use cachet_core::roots::{bound_project_list, build_lease_renewal, serialize_project_list};
use cachet_core::types::{ProjectName, UnixMillis};
use cachet_core::write::require_content_length;
use worker::{Env, Request, Response, Result};

use crate::{error, log};

/// JSON, uncacheable: a lease changes on every default-branch build.
fn lease_headers() -> Result<worker::Headers> {
    let headers = worker::Headers::new();
    headers.set("content-type", "application/json")?;
    headers.set("cache-control", "no-store")?;
    Ok(headers)
}

/// Renew a project's lease: a typed answer for every refusal, a 204 for a
/// stored renewal. Last write wins by design — a lease asserts what a
/// project needs now, and a path dropping out of the closure is the only
/// reason the cache stays bounded.
pub async fn renew_lease(
    env: &Env,
    config: &OidcConfig,
    identity: &cachet_core::auth::OidcIdentity,
    project: &ProjectName,
    now: UnixMillis,
    mut req: Request,
) -> Result<Response> {
    let _length = match require_content_length(
        req.headers().get("content-length")?.as_deref(),
        ROOTS_BODY_BYTES_MAX,
    ) {
        Ok(length) => length,
        Err(code) => return error::problem_response(code),
    };
    let body_text = req.text().await.map_err(|_| ClientError::MalformedRoots);
    let body_text = match body_text {
        Ok(text) => text,
        Err(code) => return error::problem_response(code),
    };
    let lease = match build_lease_renewal(project, &body_text, identity, config, now) {
        Ok(lease) => lease,
        Err(code) => {
            log::event(
                "warn",
                "roots.renewal_rejected",
                &[
                    ("project", project.as_str().to_string()),
                    ("code", code.code().to_string()),
                ],
            );
            return error::problem_response(code);
        }
    };
    match env
        .bucket("CACHE_BUCKET")?
        .put(lease_key_for_project(project), lease.serialize())
        .execute()
        .await
    {
        Ok(_) => {
            log::event(
                "info",
                "roots.renewed",
                &[
                    ("project", project.as_str().to_string()),
                    ("storePaths", lease.store_paths.len().to_string()),
                    ("commitSha", lease.commit_sha.clone()),
                ],
            );
            Ok(Response::empty()?.with_status(204))
        }
        Err(failure) => {
            log::event(
                "error",
                "roots.store_failed",
                &[("error", failure.to_string())],
            );
            error::problem_response(ClientError::StorageUnavailable)
        }
    }
}

/// List the projects holding leases, bounded and complete or refused.
/// The listing paginates with a bounded page count: a bucket past the cap
/// is reported as an overflow rather than silently truncated, because a
/// partial list is a wrong answer acting like a right one.
pub async fn list_projects(env: &Env) -> Result<Response> {
    let bucket = env.bucket("CACHE_BUCKET")?;
    let mut projects: Vec<ProjectName> = Vec::new();
    let mut cursor: Option<String> = None;
    // One page of slack past the cap: the bound below, not this loop, is
    // the final word on "too many".
    let pages = ROOTS_PROJECTS_MAX / BUCKET_LIST_PAGE_LIMIT + 1;
    for _page in 0..=pages {
        let mut builder = bucket
            .list()
            .prefix(cachet_core::constants::ROOTS_KEY_PREFIX)
            .limit(u32::try_from(BUCKET_LIST_PAGE_LIMIT).expect("the page limit fits u32"));
        if let Some(cursor) = &cursor {
            builder = builder.cursor(cursor);
        }
        let listed = match builder.execute().await {
            Ok(listed) => listed,
            Err(failure) => {
                log::event(
                    "error",
                    "roots.list_failed",
                    &[("error", failure.to_string())],
                );
                return error::problem_response(ClientError::StorageUnavailable);
            }
        };
        for object in listed.objects() {
            if let Ok(project) = project_from_lease_key(&object.key()) {
                projects.push(project);
            }
        }
        if !listed.truncated() {
            break;
        }
        cursor = listed.cursor();
    }
    if let Err(code) = bound_project_list(&projects) {
        log::alert("roots.too_many_projects");
        return error::problem_response(code);
    }
    let body = serialize_project_list(&projects);
    Ok(Response::ok(body)?.with_headers(lease_headers()?))
}

/// Serve one lease document verbatim.
pub async fn read_lease(env: &Env, project: &ProjectName) -> Result<Response> {
    let bucket = env.bucket("CACHE_BUCKET")?;
    match bucket.get(lease_key_for_project(project)).execute().await? {
        None => error::problem_response(ClientError::NotFound),
        Some(object) => {
            let Some(body) = object.body() else {
                return error::problem_response(ClientError::StorageUnavailable);
            };
            let text = body.text().await?;
            Ok(Response::ok(text)?.with_headers(lease_headers()?))
        }
    }
}

