          "utf8",
        );
        assert.equal(
          await spec.text(),
          committed,
          "the served document is the committed one",
        );
      });
"""
open('workerd/check.mjs','w').write(text.replace(old, new))
print('split')
EOF
node --check workerd/check.mjs && echo OK

