2	//! mechanics, and URL construction. Every decision here is pure data; the
3	//! pipeline executes what these functions answer.
4	
5	use cachet_core::constants::UPLOAD_SINGLE_MAX_BYTES;
6	use cachet_core::multipart::{PlanShape, plan_shape};
7	
8	use crate::error::PushError;
9	
10	/// One object as the staging directory reports it.
11	#[derive(Debug, Clone, PartialEq, Eq)]
12	pub struct StagedObject {
13	    /// The bucket key and request path: the staging-relative path.
14	    pub key: String,
15	    /// Its size in bytes.
16	    pub size_bytes: u64,
17	    /// The staging filename: the key minus any leading `nar/`.
18	    pub file_name: String,
19	}
20	
21	impl StagedObject {
22	    /// Whether the object rides the narinfo ordering slot.
23	    pub fn is_narinfo(&self) -> bool {
24	        self.key.ends_with(cachet_core::constants::NARINFO_KEY_SUFFIX)
25	    }
26	}
27	
28	/// Read a staging directory's layout the nix way: top-level `*.narinfo`
29	/// files, and the object files under `nar/`. Everything else is the
30	/// pipeline's own noise and fails the read.
31	///
32	/// # Errors
33	///
34	/// [`PushError::StagingUnreadable`] for an entry that fits neither shape.
35	pub fn read_staging_layout(entries: &[(String, u64)]) -> Result<Vec<StagedObject>, PushError> {
36	    let mut objects = Vec::with_capacity(entries.len());
37	    for (name, size_bytes) in entries {
38	        let key = if name.ends_with(cachet_core::constants::NARINFO_KEY_SUFFIX)
39	            && !name.contains('/')
40	        {
41	            name.clone()
42	        } else if let Some(rest) = name.strip_prefix("nar/") {
43	            if rest.contains('/') {
44	                return Err(PushError::StagingUnreadable {
45	                    message: format!("{name} nests deeper than nar/"),
46	                });
47	            }
48	            name.clone()
49	        } else {
50	            return Err(PushError::StagingUnreadable {
51	                message: format!("{name} fits neither the narinfo shape nor nar/"),
52	            });
53	        };
54	        objects.push(StagedObject {
55	            file_name: key
56	                .strip_prefix("nar/")
57	                .map_or_else(|| key.clone(), str::to_string),
58	            key,
59	            size_bytes: *size_bytes,
60	        });
61	    }
62	    Ok(objects)
63	}
64	
65	/// The upload order: every NAR before every narinfo, stable inside each
66	/// kind, because the cache refuses a narinfo whose NAR is absent
67	/// (NEVER-DANGLE).
68	pub fn upload_order(objects: &mut [StagedObject]) {
69	    objects.sort_by_key(|object| object.is_narinfo());
70	}
71	
72	/// One object's ride: the whole body in one PUT, or the multipart
73	/// quartet.
74	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
75	pub enum UploadMechanics {
76	    /// `PUT /{key}` with the whole body.
77	    Single,
78	    /// The multipart plan: part count and final length from the shared
79	    /// part math.
80	    Multipart(PlanShape),
81	}
82	
83	/// Decide the mechanics. Nix's stat answers the size; an implausible
84	/// answer fails before any byte moves. The single-PUT cap compares
85	/// inclusively: exactly-at-cap rides single, as the worker's guard
86	/// agrees. The multipart refusal delegates to the shared plan's own
87	/// reasoning.
88	///
89	/// # Errors
90	///
91	/// [`PushError::TooLarge`] past the parts cap;
92	/// [`PushError::ImplausibleSize`]!? — sizes come from stat so this branch
93	/// exists for completeness against adapters, expecting never to fire.
94	pub fn plan_mechanics(key: &str, size_bytes: u64) -> Result<UploadMechanics, PushError> {
95	    if size_bytes <= UPLOAD_SINGLE_MAX_BYTES {
96	        return Ok(UploadMechanics::Single);
97	    }
98	    plan_shape(size_bytes)
99	        .map(UploadMechanics::Multipart)
