17	/// The probe pool's width: bounded fan-out for presence checks, matching
18	/// the previous pipeline's tuning.
19	const PROBE_CONCURRENCY: usize = 16;
20	
21	/// The values the composite resolves once into the job environment.
22	#[derive(Debug, Clone, PartialEq, Eq)]
23	pub struct PushInputs {
24	    /// The cache's base URL.
25	    pub cache_url: String,
26	    /// The OIDC audience.
27	    pub audience: String,
28	    /// The lease name: `owner-repo` hyphenated.
29	    pub project: String,
30	    /// The flake installables whose closures root this push.
31	    pub installables: Vec<String>,
32	    /// The upstream substituter to filter against.
33	    pub upstream_url: String,
34	    /// Whether this run answers for the configured default branch.
35	    pub is_default_branch: bool,
36	}
37	
38	/// What the push did, for the caller's log lines.
39	#[derive(Debug, Clone, PartialEq, Eq, Default)]
40	pub struct PushOutcome {
41	    /// Candidates from the diff.
42	    pub added_paths: usize,
43	    /// Paths kept because the roots named them.
44	    pub roots_kept: usize,
45	    /// Paths the upstream already serves.
46	    pub upstream_hits: usize,
47	    /// Paths cachet already held.
48	    pub cache_hits: usize,
49	    /// Probes that answered nothing.
50	    pub probe_failures: usize,
51	    /// Objects (NAR plus narinfo files) uploaded.
52	    pub uploaded_objects: usize,
53	    /// Whether the lease renewed on this run.
54	    pub lease_renewed: bool,
55	}
56	
57	/// Progress the caller renders. Each variant names one past-tense fact.
58	#[derive(Debug, Clone, PartialEq, Eq)]
59	pub enum PushEvent {
60	    /// The before-snapshot wrote.
61	    SnapshotTaken,
62	    /// The before-snapshot could not be taken; the push declines.
63	    MainSnapshotFailed {
64	        /// The command's complaint.
65	        message: String,
66	    },
67	    /// The job added nothing to the store.
68	    NothingAdded,
69	    /// One installable would not resolve and rides the lease unnamed.
70	    InstallableUnresolved {
71	        /// The installable as given.
72	        installable: String,
73	    },
74	    /// Pass one's tally.
75	    UpstreamTally {
76	        /// Paths still bound for pushing.
77	        to_push: usize,
78	        /// Paths the upstream already serves.
79	        upstream_hits: usize,
80	        /// Probes with no answer.
81	        probe_failures: usize,
82	    },
83	    /// Pass two's tally.
84	    CacheTally {
85	        /// Paths still bound for upload.
86	        to_upload: usize,
87	        /// Paths cachet already held.
88	        cache_hits: usize,
89	        /// Probes with no answer.
90	        probe_failures: usize,
91	    },
92	    /// All surviving objects landed.
93	    UploadedObjects {
94	        /// Narinfo plus NAR file count.
95	        count: usize,
96	    },
97	    /// The renewal's branch gate refused.
98	    LeaseSkippedNotDefaultBranch,
99	    /// The lease renewed.
100	    LeaseRenewed {
101	        /// The project it covers.
102	        project: String,
103	    },
104	}
105	
106	/// One sleep, injected so the unit lane never waits.
107	pub type Sleeper = dyn Fn(u64) -> futures_util::future::BoxFuture<'static, ()> + Send + Sync;
108	
109	/// The composite's main step: snapshot, or decline gracefully. A command
110	/// failure answers `None` with its event — the job must finish green.
111	pub async fn main_snapshot<C: Commands>(
112	    commands: &C,
113	    events: &mut dyn FnMut(PushEvent),
114	) -> Result<Option<String>, PushError> {
115	    match commands.path_info_all().await {
116	        Ok(text) => {
117	            events(PushEvent::SnapshotTaken);
118	            Ok(Some(text))
119	        }
120	        Err(failure) => {
121	            events(PushEvent::MainSnapshotFailed {
122	                message: failure.to_string(),
123	            });
124	            Ok(None)
125	        }
126	    }
127	}
128	
129	/// The post step: diff, filter, stage, upload, renew. The pipeline's
130	/// result IS the job's diagnosis; the caller decides what green means.
131	pub async fn push<C: Commands, H: Http, T: TokenSource>(
132	    commands: &C,
133	    http: &H,
134	    tokens: &T,
135	    sleep: &Sleeper,
136	    inputs: &PushInputs,
137	    before_snapshot: &str,
138	    staging_dir: &std::path::Path,
139	    events: &mut dyn FnMut(PushEvent),
140	) -> Result<PushOutcome, PushError> {
141	    let mut outcome = PushOutcome::default();
142	
143	    let after = commands.path_info_all().await?;
144	    let candidates = store_diff(before_snapshot, &after);
145	    bound_candidates(&candidates)?;
146	    outcome.added_paths = candidates.len();
147	    if candidates.is_empty() {
148	        events(PushEvent::NothingAdded);
149	        return Ok(outcome);
150	    }
151	
152	    // Roots resolve best-effort: an unresolvable installable still rides
153	    // the lease by name; only its paths are missing.
154	    let mut resolved_root_paths: Vec<String> = Vec::new();
155	    for installable in &inputs.installables {
156	        match commands.path_info(installable).await {
157	            Ok(text) => resolved_root_paths.extend(parse_snapshot(&text)),
158	            Err(_) => events(PushEvent::InstallableUnresolved {
159	                installable: installable.clone(),
160	            }),
161	        }
162	    }
163	    let root_set: std::collections::BTreeSet<String> =
164	        resolved_root_paths.iter().cloned().collect();
165	    outcome.roots_kept = candidates
166	        .iter()
167	        .filter(|path| root_set.contains(*path))
168	        .count();
169	
170	    // Pass one: upstream. Probes fan out sixteen wide, answers ordered.
171	    let probe_token = tokens.mint(&inputs.audience).await?;
172	    let upstream_answers = probe_pool(http, &inputs.upstream_url, None, &candidates).await;
173	    let upstream = filter_against_upstream(&candidates, &root_set, &|path| {
174	        upstream_answers
175	            .iter()
176	            .find(|(candidate, _)| candidate == path)
177	            .and_then(|(_, answer)| *answer)
178	    });
179	    outcome.upstream_hits = upstream.upstream_hits;
180	    outcome.probe_failures += upstream.probe_failures;
181	    events(PushEvent::UpstreamTally {
182	        to_push: upstream.kept.len(),
183	        upstream_hits: upstream.upstream_hits,
184	        probe_failures: upstream.probe_failures,
185	    });
186	    if upstream.kept.is_empty() {
187	        return finish_with_lease(http, tokens, sleep, inputs, events, outcome, &resolved_root_paths)
188	            .await;
189	    }
190	
191	    // Pass two: cachet itself.
192	    let cache_answers = probe_pool(http, &inputs.cache_url, Some(&probe_token), &upstream.kept).await;
193	    let cached = drop_already_cached(&upstream.kept, &|path| {
194	        cache_answers
195	            .iter()
196	            .find(|(candidate, _)| candidate == path)
197	            .and_then(|(_, answer)| *answer)
198	    });
199	    outcome.cache_hits = cached.cache_hits;
200	    outcome.probe_failures += cached.probe_failures;
201	    events(PushEvent::CacheTally {
202	        to_upload: cached.to_upload.len(),
203	        cache_hits: cached.cache_hits,
204	        probe_failures: cached.probe_failures,
205	    });
206	    if cached.to_upload.is_empty() {
207	        return finish_with_lease(http, tokens, sleep, inputs, events, outcome, &resolved_root_paths)
208	            .await;
209	    }
