8	/// The two environment variables the mint answers to. Their absence is a
9	/// configuration fact with its own sentence, because the fix lives in the
10	/// job's YAML, not here.
11	#[derive(Debug)]
12	pub struct OidcEnv {
13	    /// `ACTIONS_ID_TOKEN_REQUEST_URL`, verbatim.
14	    pub request_url: String,
15	    /// `ACTIONS_ID_TOKEN_REQUEST_TOKEN`, verbatim.
16	    pub request_token: String,
17	}
18	
19	/// Read the mint's environment from explicit pairs, so tests never touch
20	/// ambient state.
21	///
22	/// # Errors
23	///
24	/// [`PushError::OidcUnavailable`] naming the YAML fix.
25	pub fn oidc_env(vars: &[(String, String)]) -> Result<OidcEnv, PushError> {
26	    let find = |name: &str| vars.iter().find(|(key, _)| key == name).map(|(_, v)| v.clone());
27	    let url = find("ACTIONS_ID_TOKEN_REQUEST_URL");
28	    let token = find("ACTIONS_ID_TOKEN_REQUEST_TOKEN");
29	    match (url, token) {
30	        (Some(request_url), Some(request_token)) if !request_url.is_empty() && !request_token.is_empty() => {
31	            Ok(OidcEnv {
32	                request_url,
33	                request_token,
34	            })
35	        }
36	        _ => Err(PushError::OidcUnavailable(
37	            "no OIDC token request variables. Add `permissions: { id-token: write }` to the job.".to_string(),
38	        )),
39	    }
40	}
41	
42	/// RFC 3986 unreserved pass-through for the audience parameter.
43	fn encode_component(value: &str) -> String {
44	    use std::fmt::Write as _;
45	    const UNRESERVED: &[u8] = b"REDACTED._~";
46	    let mut out = String::with_capacity(value.len());
47	    for byte in value.as_bytes() {
48	        if UNRESERVED.contains(byte) {
49	            out.push(char::from(*byte));
50	        } else {
51	            let _ = write!(out, "%{byte:02X}");
52	        }
53	    }
54	    out
55	}
