    let big = cachet_core::constants::UPLOAD_SINGLE_MAX_BYTES + 13;
    let commands = FakeCommands::with_store(&format!("{BUILT}\n"));
    commands
        .layout
        .lock()
        .expect("layout")
        .extend([(format!("nar/{}.nar.zst", "n".repeat(52)), big)]);
