    http.post(
        &format!("https://cachet.test/{nar_key}?uploads"),
        200,
        r#"{"uploadId":"up-1","expectedParts":2}"#,
    );
    http.fail_put(
        &format!("https://cachet.test/{nar_key}?uploadId=up-1&partNumber=1"),
        "connection reset",
