168	    let probe_token = a.tokens.mint(&inputs.audience).await?;
169	    let upstream_answers = probe_pool(a.http, &inputs.upstream_url, None, &candidates).await;
170	    let upstream = filter_against_upstream(&candidates, &root_set, &|path| {
171	        upstream_answers
172	            .iter()
173	            .find(|(candidate, _)| candidate == path)
174	            .and_then(|(_, answer)| *answer)
175	    });

