        );
    }

    #[test]
    fn netrc_rewrite_is_idempotent() {
        let once = netrc_replace_block("", "cache.example.com", "tok");
        let twice = netrc_replace_block(&once, "cache.example.com", "tok");
        assert_eq!(once, twice);
    }

