                "netrc-file = /etc/nix/netrc\n",
                "extra-substituters = https://cache.nixos.org https://old.invalid https://cache.example.com\n",
                "extra-trusted-public-keys = cache.nixos.org-1:aaaa cache.example.com-1:bbbb\n",
