        assert_eq!(
            outcome,
            ReloadOutcome::Launchctl("systems.determinate.nix-daemon".to_string())
        );
        let log = ran.lock().expect("log");
        assert_eq!(log[0], vec!["systemctl", "restart", "nix-daemon"]);
