    fn resolution_defaults_and_branch_gate() {
        let resolved = resolve_env(&vars(&[
            ("CACHET_CACHE_URL", "https://cache.example.com"),
            ("CACHET_AUDIENCE", "cachet"),
            ("CACHET_PROJECT", "org-repo"),
            ("CACHET_ROOTS", ".#a  .#b\n.#c"),
            ("GITHUB_REF", "refs/heads/main"),
        ]));
