//! The doctor probe: answers "is this machine wired to read" the way an
//! operator does, but mechanically. The load-bearing distinction is
//! 404-versus-401: the worker authenticates before it consults the
//! bucket, so a 404 proves the credential works (the probed hash is
//! simply absent) and a 401 proves it does not.

use crate::CliError;

/// One check's outcome. `ok` answers the summary; `detail` explains the
/// failure to the human reading it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Probe {
    /// What was checked, one short clause.
    pub name: String,
    /// Whether it held.
    pub ok: bool,
    /// What the check answer meant, or what to do about it.
    pub detail: String,
}

impl Probe {
    fn pass(name: &str, detail: String) -> Self {
        Self {
            name: name.to_string(),
            ok: true,
            detail,
        }
    }

    fn fail(name: &str, detail: String) -> Self {
        Self {
            name: name.to_string(),
            ok: false,
            detail,
        }
    }
}

/// A hash that parses but cannot exist: all zero bits but the last.
const PROBE_NARINFO: &str = "0000000000000000000000000000000a.narinfo";

/// Run every probe against one deployment: the unauthenticated health
/// document, the public config, the refusal of an anonymous read, and —
/// when a token is stored — the authenticated read and GitHub identity.
/// `token` is what the state directory held for this host (absence is
/// itself a probe outcome, not an error).
pub async fn run_doctor(
    client: &reqwest::Client,
    cache_url: &str,
    token: Option<&str>,
    api_base: &str,
) -> Vec<Probe> {
    let mut probes = Vec::new();

    match client
        .get(format!("{cache_url}/nix-cache-info"))
        .send()
        .await
    {
        Ok(answer) if answer.status().is_success() => {
            let body = answer.text().await.unwrap_or_default();
            if body.contains("StoreDir: /nix/store") {
                probes.push(Probe::pass(
                    "the cache answers /nix-cache-info",
                    format!("{cache_url} is serving"),
                ));
            } else {
                probes.push(Probe::fail(
                    "the cache answers /nix-cache-info",
                    "the body names no store dir: is this a cachet deployment?".to_string(),
                ));
            }
        }
        Ok(answer) => probes.push(Probe::fail(
            "the cache answers /nix-cache-info",
            format!("answered {}", answer.status().as_u16()),
        )),
        Err(failure) => probes.push(Probe::fail(
            "the cache answers /nix-cache-info",
            format!("no answer: {failure}"),
        )),
    }

    let config = match crate::login::fetch_public_config(client, cache_url).await {
        Ok(config) => {
            probes.push(Probe::pass(
                "the public config serves",
                format!(
                    "host {}, orgs [{}], key {}",
                    config.host,
                    config.orgs.join(", "),
                    config.public_key.split(':').next().unwrap_or("?")
                ),
            ));
            Some(config)
        }
        Err(failure) => {
            probes.push(Probe::fail("the public config serves", failure.to_string()));
            None
        }
    };

    let probe_url = format!("{cache_url}/{PROBE_NARINFO}");
    match client.get(&probe_url).send().await {
        Ok(answer) if answer.status().as_u16() == 401 => probes.push(Probe::pass(
            "anonymous reads refuse",
            "401 before the bucket, as the auth order requires".to_string(),
        )),
        Ok(answer) => probes.push(Probe::fail(
            "anonymous reads refuse",
            format!(
                "answered {} instead of 401: the read guard is misconfigured",
                answer.status().as_u16()
            ),
        )),
        Err(failure) => probes.push(Probe::fail(
            "anonymous reads refuse",
            format!("no answer: {failure}"),
        )),
    }

    let Some(token) = token else {
        probes.push(Probe::fail(
            "a stored login exists",
            format!("no token for this host: run `cachet login --cache-url {cache_url}`"),
        ));
        return probes;
    };
    probes.push(Probe::pass(
        "a stored login exists",
        "the state directory holds a token".to_string(),
    ));

    match client.get(&probe_url).bearer_auth(token).send().await {
        Ok(answer) if answer.status().as_u16() == 404 => probes.push(Probe::pass(
            "the stored token reads",
            "404 means authenticated-and-absent: the wiring works".to_string(),
        )),
        Ok(answer) if answer.status().is_success() => probes.push(Probe::pass(
            "the stored token reads",
            "the probe path unexpectedly exists, which still proves auth".to_string(),
        )),
        Ok(answer) => probes.push(Probe::fail(
            "the stored token reads",
            format!(
                "answered {}: re-run `cachet login`; if that holds, the token's org membership lapsed",
                answer.status().as_u16()
            ),
        )),
        Err(failure) => probes.push(Probe::fail(
            "the stored token reads",
            format!("no answer: {failure}"),
        )),
    }

    match client
        .get(format!("{api_base}/user"))
        .bearer_auth(token)
        .send()
        .await
    {
        Ok(answer) if answer.status().is_success() => {
            #[derive(serde::Deserialize)]
            struct User {
                login: Option<String>,
            }
            match answer.json::<User>().await {
                Ok(User { login: Some(login) }) => probes.push(Probe::pass(
                    "the token identifies",
                    format!("authenticates as {login}"),
                )),
                _ => probes.push(Probe::fail(
                    "the token identifies",
                    "GitHub answered without a login".to_string(),
                )),
            }
        }
        Ok(answer) => probes.push(Probe::fail(
            "the token identifies",
            format!(
                "GitHub answered {}: the token is revoked or expired; run `cachet login` again",
                answer.status().as_u16()
            ),
        )),
        Err(failure) => probes.push(Probe::fail(
            "the token identifies",
            format!("no answer: {failure}"),
        )),
    }

    if let Some(config) = config {
        let mut memberships = 0_usize;
        let mut denied_orgs: Vec<String> = Vec::new();
        for org in &config.orgs {
            let url = format!("{api_base}/user/memberships/orgs/{org}");
            match client.get(&url).bearer_auth(token).send().await {
                Ok(answer) if answer.status().is_success() => memberships += 1,
                _ => denied_orgs.push(org.clone()),
            }
        }
        if memberships > 0 {
            probes.push(Probe::pass(
                "org membership holds",
                format!("a member of {memberships} served org(s)"),
            ));
        } else {
            probes.push(Probe::fail(
                "org membership holds",
                format!(
                    "a member of none of [{}]: the worker will refuse every read",
                    denied_orgs.join(", ")
                ),
            ));
        }
    }

    probes
}

/// Render the probe list in the report's shape: an `ok`/`FAIL` line per
/// probe. Answers whether everything held.
#[must_use]
pub fn render(probes: &[Probe]) -> (Vec<String>, bool) {
    let mut all_ok = true;
    let mut lines = Vec::new();
    for probe in probes {
        if probe.ok {
            lines.push(format!("ok   {}: {}", probe.name, probe.detail));
        } else {
            all_ok = false;
            lines.push(format!("FAIL {}: {}", probe.name, probe.detail));
        }
    }
    (lines, all_ok)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn render_separates_ok_from_fail() {
        let probes = vec![
            Probe::pass("a", "fine".to_string()),
            Probe::fail("b", "broken".to_string()),
        ];
        let (lines, all_ok) = render(&probes);
        assert!(!all_ok);
        assert_eq!(lines[0], "ok   a: fine");
        assert_eq!(lines[1], "FAIL b: broken");
        let (happy, all_ok) = render(&[Probe::pass("a", "fine".to_string())]);
        assert!(all_ok);
        assert_eq!(happy.len(), 1);
    }
}

