8	/// github.com's web half: device code and token polls.
9	pub const GITHUB_WEB_BASE: &str = "https://github.com";
10	/// The API half: identity checks.
11	pub const GITHUB_API_BASE: &str = "https://api.github.com";
12	
13	/// The scope laptop reads need: org membership is the worker's whole
14	/// admission test.
15	const DEVICE_SCOPE: &str = "read:org";
