21	/// What a poll of the token endpoint answered.
22	#[derive(Debug, Clone, PartialEq, Eq)]
23	pub enum PollAnswer {
24	    /// The user has not entered the code yet.
25	    Pending,
26	    /// The server asked for a longer interval.
27	    SlowDown,
28	    /// The flow completed.
29	    Granted {
30	        /// The OAuth user token.
31	        token: String,
32	    },
33	    /// The device code lapsed before the user finished.
34	    Expired,
35	    /// The user declined.
36	    Denied {
37	        /// GitHub's own reason text.
38	        description: String,
39	    },
40	}
