81	/// Fetch the deployment's public config: the OAuth App's client id, the
82	/// orgs, the host name, and the key laptops learn to trust.
83	///
84	/// # Errors
85	///
86	/// [`CliError`] when the URL answers badly or the body is not the
87	/// document.
88	pub async fn fetch_public_config(
89	    client: &reqwest::Client,
90	    cache_url: &str,
91	) -> Result<cachet_api::PublicConfig, CliError> {
92	    let url = format!("{cache_url}/api/public/config");
93	    let answer = client
94	        .get(&url)
95	        .send()
96	        .await
97	        .map_err(|failure| CliError(format!("{url} did not answer: {failure}")))?;
98	    if !answer.status().is_success() {
99	        return Err(CliError(format!(
100	            "{url} answered {}: this cache is not serving its public config",
101	            answer.status().as_u16()
102	        )));
103	    }
104	    answer
105	        .json::<cachet_api::PublicConfig>()
106	        .await
107	        .map_err(|failure| CliError(format!("{url} did not return a public config: {failure}")))
