110	/// Drive one flow: emit the instructions, poll until an outcome, and
111	/// identify the human at the end. Answers the token and the login it
112	/// authenticates as.
113	///
114	/// # Errors
115	///
116	/// [`CliError`] on denial, expiry, transport failures, or a server that
117	/// stops making sense.
118	pub async fn run_device_flow<D: DeviceServer>(
119	    server: &D,
120	    client_id: &str,
121	    sleep_ms: &Sleeper,
122	    tell: &mut dyn FnMut(&str),
123	) -> Result<(String, String), CliError> {
124	    let session = server.start(client_id, DEVICE_SCOPE).await?;
125	    tell(&format!(
126	        "cachet: open {} and enter {}",
127	        session.verification_uri, session.user_code
128	    ));
129	    let mut interval_ms = session.interval_secs.max(1) * 1000;
130	    let mut waited_ms = 0_u64;
131	    let budget_ms = session.expires_in_secs.max(1) * 1000;
132	    let token = loop {
133	        sleep_ms(interval_ms).await;
134	        waited_ms += interval_ms;
135	        if waited_ms > budget_ms {
136	            return Err(CliError(
137	                "the device code expired before the flow finished; run `cachet login` again"
138	                    .to_string(),
139	            ));
140	        }
141	        match server.poll(client_id, &session.device_code).await? {
142	            PollAnswer::Pending => {}
143	            PollAnswer::SlowDown => interval_ms += 5000,
144	            PollAnswer::Granted { token, .. } => break token,
145	            PollAnswer::Expired => {
146	                return Err(CliError(
147	                    "the device code expired; run `cachet login` again".to_string(),
148	                ));
149	            }
150	            PollAnswer::Denied { description } => {
151	                return Err(CliError(format!(
152	                    "the flow was declined{}",
153	                    if description.is_empty() {
154	                        String::new()
155	                    } else {
156	                        format!(": {description}")
157	                    }
158	                )));
159	            }
160	        }
161	    };
162	    let login = server.whoami(&token).await?;
163	    Ok((token, login))
164	}
