1	//! The CI driver: turns the job environment into pipeline inputs and
2	//! renders the pipeline's events as the `cachet:` log vocabulary. The
3	//! composite action exports the CACHET_* variables; this module resolves,
4	//! never the other way around, so running the binary standalone answers
5	//! the same missing-input diagnosis the action would.
6	//!
7	//! The contract on failure is the previous post step's: log and exit
8	//! zero. A broken push must never break the build it rides on.
9	
10	use cachet_push::pipeline::PushEvent;
11	
12	use crate::CliError;
13	
14	/// Every variable the post phase reads, resolved.
15	#[derive(Debug, Clone, PartialEq, Eq)]
16	pub struct PushEnv {
17	    /// Where the cache lives.
18	    pub cache_url: String,
19	    /// The OIDC audience.
20	    pub audience: String,
21	    /// The lease project (`owner-repo`).
22	    pub project: String,
23	    /// Whitespace-split flake installables.
24	    pub installables: Vec<String>,
25	    /// The upstream filter target.
26	    pub upstream_url: String,
27	    /// GITHUB_REF == CACHET_DEFAULT_BRANCH_REF, both nonempty.
28	    pub is_default_branch: bool,
29	    /// RUNNER_TEMP, where the snapshot between main and post lives.
30	    pub runner_temp: std::path::PathBuf,
31	}
32	
33	/// What resolving the environment concluded.
34	#[derive(Debug, Clone, PartialEq, Eq)]
35	pub enum EnvResolution {
36	    /// `CACHET_PUSH=false`: the job read-only.
37	    Disabled,
38	    /// Everything needed is present.
39	    Ready(PushEnv),
40	    /// These variables are unset or empty.
41	    Missing(Vec<String>),
42	}
43	
44	/// The default upstream filter, when the job does not say.
45	const UPSTREAM_DEFAULT: &str = "https://cache.nixos.org";
46	/// The default renewal ref, when the job does not say.
47	const DEFAULT_BRANCH_REF: &str = "refs/heads/main";
48	
49	/// Resolve the job environment. Resolution is data-in, answers-out: the
50	/// caller collects `std::env::vars` once.
51	#[must_use]
52	pub fn resolve_env(vars: &[(String, String)]) -> EnvResolution {
53	    let value = |name: &str| {
54	        vars.iter()
55	            .find(|(key, _)| key == name)
56	            .map(|(_, v)| v.trim().to_string())
57	            .filter(|v| !v.is_empty())
58	    };
59	    if value("CACHET_PUSH").as_deref() == Some("false") {
60	        return EnvResolution::Disabled;
61	    }
62	    let cache_url = value("CACHET_CACHE_URL");
63	    let audience = value("CACHET_AUDIENCE");
64	    let project = value("CACHET_PROJECT");
65	    let missing: Vec<String> = [
66	        ("CACHET_CACHE_URL", cache_url.is_none()),
67	        ("CACHET_AUDIENCE", audience.is_none()),
68	        ("CACHET_PROJECT", project.is_none()),
69	    ]
70	    .into_iter()
71	    .filter(|(_, absent)| *absent)
72	    .map(|(name, _)| name.to_string())
73	    .collect();
74	    let (Some(cache_url), Some(audience), Some(project)) = (cache_url, audience, project)
75	    else {
76	        return EnvResolution::Missing(missing);
77	    };
78	    let upstream_url = value("CACHET_UPSTREAM_URL").unwrap_or_else(|| UPSTREAM_DEFAULT.to_string());
79	    let default_ref = value("CACHET_DEFAULT_BRANCH_REF").unwrap_or_else(|| DEFAULT_BRANCH_REF.to_string());
80	    let github_ref = value("GITHUB_REF");
81	    let is_default_branch = matches!(github_ref, Some(actual) if actual == default_ref);
82	    let installables = value("CACHET_ROOTS")
83	        .map(|roots| roots.split_whitespace().map(str::to_string).collect())
84	        .unwrap_or_default();
85	    let runner_temp = value("RUNNER_TEMP")
86	        .map(std::path::PathBuf::from)
87	        .unwrap_or_else(|| std::path::PathBuf::from("/tmp"));
88	    EnvResolution::Ready(PushEnv {
89	        cache_url,
90	        audience,
91	        project,
92	        installables,
93	        upstream_url,
94	        is_default_branch,
95	        runner_temp,
96	    })
97	}
