99	/// The missing-input diagnosis, verbatim the previous post step's shape:
100	/// one sentence naming what to set and who normally sets it.
101	#[must_use]
102	pub fn missing_message(missing: &[String]) -> String {
103	    format!(
104	        "cachet: nothing pushed, because {} {} unset. The cachet setup action exports these to the job environment; if you are running cachet push directly, set them yourself.",
105	        missing.join(", "),
106	        if missing.len() == 1 { "is" } else { "are" },
107	    )
108	}
109	
110	/// The `cachet:` vocabulary: one line per event, matching the previous
111	/// post step's wording so existing log scanners keep working.
112	#[must_use]
113	pub fn render_event(event: &PushEvent) -> String {
114	    match event {
115	        PushEvent::SnapshotTaken => "cachet: store snapshot taken".to_string(),
116	        PushEvent::MainSnapshotFailed { message } => {
117	            format!("cachet: could not snapshot the store, so nothing will be pushed. {message}")
118	        }
119	        PushEvent::NothingAdded => "cachet: the job added nothing to the store".to_string(),
120	        PushEvent::InstallableUnresolved { installable } => {
121	            format!("cachet: could not resolve {installable}; it will not be a lease root")
122	        }
123	        PushEvent::UpstreamTally {
124	            to_push,
125	            upstream_hits,
126	            probe_failures,
127	        } => tally_line(
128	            &format!("{to_push} not upstream, {upstream_hits} already upstream"),
129	            *probe_failures,
130	        ),
131	        PushEvent::CacheTally {
132	            to_upload,
133	            cache_hits,
134	            probe_failures,
135	        } => tally_line(
136	            &format!("{to_upload} new to cachet, {cache_hits} already cached"),
137	            *probe_failures,
138	        ),
139	        PushEvent::UploadedObjects { count } => format!("cachet: uploaded {count} objects"),
140	        PushEvent::LeaseSkippedNotDefaultBranch => {
141	            "cachet: not the default branch, so the lease is not renewed".to_string()
142	        }
143	        PushEvent::LeaseRenewed { project } => format!("cachet: lease renewed for {project}"),
144	    }
145	}
146	
147	fn tally_line(base: &str, probe_failures: usize) -> String {
148	    if probe_failures == 0 {
149	        format!("cachet: {base}")
150	    } else {
151	        format!("cachet: {base}, {probe_failures} probes failed (kept)")
152	    }
153	}
