155	/// The main step: snapshot the store to the hand-off file. Failures are
156	/// reported and swallowed; the post step treats a missing file as an
157	/// empty before-set.
158	pub async fn run_snapshot(
159	    vars: &[(String, String)],
160	    commands: &cachet_push::real::TokioCommands,
161	    tell: &mut dyn FnMut(&str),
162	) {
163	    let runner_temp = vars
164	        .iter()
165	        .find(|(key, _)| key == "RUNNER_TEMP")
166	        .map(|(_, v)| std::path::PathBuf::from(v))
167	        .unwrap_or_else(|| std::path::PathBuf::from("/tmp"));
168	    let path = cachet_push::adapters::snapshot_path(&runner_temp);
169	    let mut sink = |event: PushEvent| tell(&render_event(&event));
170	    match cachet_push::pipeline::main_snapshot(commands, &mut sink).await {
171	        Ok(Some(text)) => {
172	            if let Err(failure) = std::fs::write(&path, text) {
173	                tell(&format!(
174	                    "cachet: could not write the snapshot file {}: {failure}, so nothing will be pushed",
175	                    path.display()
176	                ));
177	            }
178	        }
179	        Ok(None) => {}
180	        Err(failure) => {
181	            tell(&format!("cachet: the snapshot failed unexpectedly: {failure}"));
182	        }
183	    }
184	}
185	
186	/// The post step: the whole pipeline, never failing the job.
187	pub async fn run_push(vars: &[(String, String)], tell: &mut dyn FnMut(&str)) {
