1	//! The setup command's half: land the read token where the nix daemon
2	//! can see it (the daemon's netrc, not the user's), point the config at
3	//! the cache and its signing key, and restart the daemon so the new
4	//! configuration is live. The merge semantics port the previous login
5	//! script's exactly: block-aware netrc replacement so no orphaned
6	//! credential lines survive, word-merging key-value config so unrelated
7	//! lines pass through untouched, and the Determinate divergence where
8	//! the netrc reaches the daemon by registration instead of by
9	//! `netrc-file`.
10	
11	use std::fmt::Write as _;
12	use std::path::{Path, PathBuf};
13	
14	use crate::CliError;
15	
16	/// Everything the edits need, resolved once by the caller: the values
17	/// that go in, and the places they go.
18	#[derive(Debug, Clone, PartialEq, Eq)]
19	pub struct SetupInput {
20	    /// The cache's base URL; its host names the netrc machine and its
21	    /// whole URL becomes the substituter.
22	    pub cache_url: String,
23	    /// The deployment's public key in nix's `name:base64` form.
24	    pub public_key: String,
25	    /// The read token `cachet login` stored.
26	    pub token: String,
27	}
28	
29	/// The files this command owns, absolute. The paths are fields rather
30	/// than constants so tests write into sandboxes and operators with
31	/// unusual layouts can point elsewhere through the environment.
32	#[derive(Debug, Clone, PartialEq, Eq)]
33	pub struct SetupPaths {
34	    /// The daemon's netrc (written 0600).
35	    pub netrc: PathBuf,
36	    /// The included user config (written 0644).
37	    pub nix_custom_conf: PathBuf,
38	    /// Determinate's config, whose `additionalNetrcSources` registers the
39	    /// netrc when running under determinate-nixd.
40	    pub determinate_config: PathBuf,
41	    /// The directory macOS keeps daemon plists in; the reload ladder
42	    /// discovers nix-daemon labels here.
43	    pub launch_daemons: PathBuf,
44	    /// Whether the host runs Determinate Nix; the daemon reload order and
45	    /// the netrc-file decision both read it.
46	    pub determinate: bool,
47	}
48	
49	/// Rewrite a netrc, replacing every block that names `host` and leaving
50	/// all other blocks byte-verbatim. A block spans from its `machine` or
51	/// `default` keyword to the next one, across as many lines as it
52	/// occupies: dropping whole blocks is what keeps orphaned `password`
53	/// lines from leaking a credential for a machine the file no longer
54	/// names.
55	#[must_use]
56	pub fn netrc_replace_block(existing: &str, host: &str, token: &str) -> String {
57	    #[derive(Debug, PartialEq)]
58	    enum Kind {
59	        Preamble,
60	        Machine(String),
61	        Default,
62	    }
63	
64	    let mut spans: Vec<(Kind, &str)> = Vec::new();
65	    let mut start = 0_usize;
66	    let mut kind = Kind::Preamble;
67	    // The scanner walks whole tokens but keeps byte offsets, so kept
68	    // spans survive with their original spacing.
69	    let bytes = existing.as_bytes();
70	    let mut cursor = 0_usize;
71	    while cursor < existing.len() {
72	        while cursor < existing.len() && (bytes[cursor] as char).is_ascii_whitespace() {
73	            cursor += 1;
74	        }
75	        let token_start = cursor;
76	        while cursor < existing.len() && !(bytes[cursor] as char).is_ascii_whitespace() {
77	            cursor += 1;
78	        }
79	        let token = &existing[token_start..cursor];
80	        if token == "machine" || token == "default" {
81	            if token_start > start {
82	                spans.push((kind, &existing[start..token_start]));
83	            }
84	            if token == "machine" {
85	                while cursor < existing.len() && (bytes[cursor] as char).is_ascii_whitespace() {
86	                    cursor += 1;
87	                }
88	                let name_start = cursor;
89	                while cursor < existing.len() && !(bytes[cursor] as char).is_ascii_whitespace() {
90	                    cursor += 1;
