1	//! Where the CLI keeps its state: one directory holding one token per
2	//! deployment and the URL of the deployment last logged into, so later
3	//! commands can answer "which cache" without a flag.
4	
5	use std::path::{Path, PathBuf};
6	
7	use crate::CliError;
8	
9	/// Resolve the state directory: the explicit override, then XDG, then
10	/// the home fallback. The override exists so tests and unusual layouts
11	/// stay first-class.
12	///
13	/// # Errors
14	///
15	/// [`CliError`] when no home directory is discoverable.
16	pub fn state_dir(vars: &[(String, String)]) -> Result<PathBuf, CliError> {
17	    let value = |name: &str| {
18	        vars.iter()
19	            .find(|(key, _)| key == name)
20	            .map(|(_, v)| v.clone())
21	            .filter(|v| !v.is_empty())
22	    };
23	    if let Some(explicit) = value("CACHET_CONFIG_DIR") {
24	        return Ok(PathBuf::from(explicit));
25	    }
26	    if let Some(xdg) = value("XDG_CONFIG_HOME") {
27	        return Ok(PathBuf::from(xdg).join("cachet"));
28	    }
29	    value("HOME")
30	        .map(|home| PathBuf::from(home).join(".config").join("cachet"))
31	        .ok_or_else(|| CliError("no home directory: set CACHET_CONFIG_DIR explicitly".to_string()))
32	}
33	
34	/// The token file for one deployment, keyed by host so several caches
35	/// can share the directory.
36	fn token_path(dir: &Path, host: &str) -> PathBuf {
37	    dir.join("tokens").join(format!("{host}.token"))
38	}
39	
40	/// The file remembering which deployment was logged into most recently.
41	fn default_url_path(dir: &Path) -> PathBuf {
42	    dir.join("default-url")
43	}
44	
45	/// Persist a login: the token at 0600 under its host, and the base URL
46	/// as the new default. Re-login overwrites both, so rotation is just
47	/// logging in again.
48	///
49	/// # Errors
50	///
51	/// [`CliError`] on any write or permission failure.
52	pub fn store_login(dir: &Path, host: &str, base_url: &str, token: &str) -> Result<(), CliError> {
53	    let tokens = dir.join("tokens");
54	    std::fs::create_dir_all(&tokens)
55	        .map_err(|failure| CliError(format!("could not create {}: {failure}", tokens.display())))?;
56	    let path = token_path(dir, host);
57	    std::fs::write(&path, format!("{token}\n"))
58	        .map_err(|failure| CliError(format!("could not write {}: {failure}", path.display())))?;
59	    #[cfg(unix)]
60	    {
61	        use std::os::unix::fs::PermissionsExt as _;
62	        std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o600)).map_err(
63	            |failure| CliError(format!("could not chmod {}: {failure}", path.display())),
64	        )?;
65	    }
66	    std::fs::write(default_url_path(dir), format!("{base_url}\n")).map_err(|failure| {
67	        CliError(format!(
68	            "could not write {}: {failure}",
69	            default_url_path(dir).display()
70	        ))
71	    })?;
72	    Ok(())
73	}
74	
75	/// The stored token for a deployment, trimmed. Absence is an answer, not
76	/// a failure: `Ok(None)` means login has not happened here.
77	///
78	/// # Errors
79	///
80	/// [`CliError`] on a read failure other than absence.
81	pub fn read_token(dir: &Path, host: &str) -> Result<Option<String>, CliError> {
82	    match std::fs::read_to_string(token_path(dir, host)) {
83	        Ok(text) => Ok(text
84	            .lines()
85	            .next()
86	            .map(str::trim)
87	            .filter(|t| !t.is_empty())
88	            .map(str::to_string)),
89	        Err(miss) if miss.kind() == std::io::ErrorKind::NotFound => Ok(None),
90	        Err(failure) => Err(CliError(format!(
91	            "could not read {}: {failure}",
92	            token_path(dir, host).display()
93	        ))),
94	    }
95	}
96	
97	/// The deployment last logged into, if any.
98	#[must_use]
99	pub fn read_default_url(dir: &Path) -> Option<String> {
100	    std::fs::read_to_string(default_url_path(dir))
101	        .ok()
102	        .map(|text| text.trim().to_string())
103	        .filter(|text| !text.is_empty())
104	}
105	
106	/// The host a base URL names, for netrc and token filenames. A URL
107	/// whose host cannot be told from its path is a configuration bug, so
108	/// this fails loudly rather than guessing.
109	///
110	/// # Errors
111	///
112	/// [`CliError`] on a shape that names no host.
113	pub fn host_of(base_url: &str) -> Result<String, CliError> {
114	    let stripped = base_url
115	        .trim_end_matches('/')
116	        .strip_prefix("https://")
