            inherit cargoArtifacts;
            cargoTestExtraArgs = "--workspace --exclude cachet-worker --test property";
          }
        );

        # why: snapshots commit with their code; drift is a failed test,
        # never a silent refresh in CI.
        golden = craneLib.cargoTest (
          commonArgs
          // {
            inherit cargoArtifacts;
            INSTA_UPDATE = "no";
            cargoTestExtraArgs = "--workspace --exclude cachet-worker --test golden";
          }
        );

        # why: the non-language gates run committed scripts over committed
        # inputs inside the sandbox; the gate is the script's exit code, and
        # no git state can leak in.
        doc-manifest =
          pkgs.runCommand "doc-manifest"
            {
              nativeBuildInputs = [
                pkgs.bash
                pkgs.gawk
                pkgs.findutils
                pkgs.coreutils
                pkgs.gnugrep
                pkgs.gnused
              ];
            }
            ''
              cp ${../CLAUDE.md} CLAUDE.md
              cp ${../README.md} README.md
              cp ${../PROSE.md} PROSE.md
              cp ${../SECURITY.md} SECURITY.md
              cp -r ${../docs} docs
              cp ${../scripts/check-doc-manifest.sh} check-doc-manifest.sh
              bash ./check-doc-manifest.sh .
              touch $out
            '';

        lane-manifest =
          pkgs.runCommand "lane-manifest"
            {
              nativeBuildInputs = [
                pkgs.bash
                pkgs.gawk
                pkgs.findutils
                pkgs.coreutils
                pkgs.gnugrep
                pkgs.gnused
              ];
            }
            ''
              cp -r ${../docs} docs
              mkdir -p .github/workflows
              cp ${../.github/workflows/ci.yml} .github/workflows/ci.yml
              cp ${../scripts/check-lane-manifest.sh} check-lane-manifest.sh
              bash ./check-lane-manifest.sh .
              touch $out
            '';

        # Every workflow and action file the repo ships, with shellcheck on
        # the PATH so the `run:` blocks lint too. actionlint only detects
        # action files by their project-relative name, so the sources land
        # under a scratch project layout and the scan runs argument-free.
        # release.yml is cargo-dist's own output (regenerate, never edit):
        # it gets actionlint's syntax and expression checks in a second
        # project, but shellcheck's style findings belong to the generator,
        # so its `run:` blocks are not linted here.
        actionlint =
          pkgs.runCommand "actionlint"
            {
              nativeBuildInputs = [
                pkgs.actionlint
                pkgs.shellcheck
                pkgs.nodejs_22
              ];
            }
            ''
              mkdir -p proj/.git
              cp -r ${../.github} proj/.github
              rm -f proj/.github/workflows/release.yml
              cp -r ${../action} proj/action
              (cd proj && actionlint)
              mkdir -p proj-gen/.git proj-gen/.github/workflows
              cp ${../.github/workflows/release.yml} proj-gen/.github/workflows/release.yml
              (cd proj-gen && actionlint -shellcheck "" .github/workflows/release.yml)
              node --check ${../action/post/main.cjs}
              node --check ${../action/post/post.cjs}
              touch $out
            '';

        scripts =
          pkgs.runCommand "scripts"
            {
              nativeBuildInputs = [ pkgs.shellcheck ];
            }
            ''
              shellcheck ${../scripts}/*.sh
              touch $out
            '';
      };
    };
}

