// The deploy-time configuration contract: everything the stack needs, read
// from the environment once, with every missing value named in one refusal
// rather than discovered one failure at a time.

export interface StageConfig {
  stage: string;
  host: string;
  orgs: string;
  admins: string;
  oauthClientId: string;
  audience: string;
  defaultBranchRef: string;
  domain: string | undefined;
  uiOrigin: string | undefined;
  gcGraceMs: string | undefined;
}

const REQUIRED = ["HOST", "ORGS", "OAUTH_CLIENT_ID", "ADMINS"] as const;

export function loadStageConfig(stage: string): StageConfig {
  const value = (name: string) => process.env[`CACHET_DEPLOY_${name}`]?.trim() || undefined;
  const missing = REQUIRED.filter((name) => value(name) === undefined);
  const secretsMissing = ["CACHET_SIGNING_KEY", "GITHUB_OAUTH_CLIENT_SECRET"].filter(
    (name) => (process.env[name]?.trim() ?? "") === "",
  );
  if (missing.length > 0 || secretsMissing.length > 0) {
    const parts = [
      ...missing.map((name) => `CACHET_DEPLOY_${name}`),
      ...secretsMissing,
    ];
    throw new Error(
      `the ${stage} deployment is missing: ${parts.join(", ")}. ` +
      `Set them in infra/.env.${stage} or as environment secrets (docs/DEPLOY.md).`,
    );
  }
  const isProduction = stage === "production";
  return {
    stage,
    host: value("HOST")!,
    orgs: value("ORGS")!,
    ...
    domain: value("DOMAIN") ?? (isProduction ? value("HOST") : undefined),
    gcGraceMs: value("GC_GRACE_MS") ?? (isProduction ? undefined : "0"),
    ...
  };
}
